\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 J\u8249 \'8bohannes currit. Johannes est nominatiui casus et regitur ab illo verbo \u8218 \'82currit}}\plain \f1\i\lang1033\fs24 \lquote  a parte ante ex vi persone \plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 hew est interieccio non regitur neque regit, sed eius officium est significare mentis affectum voce incognita\plain \f1\lang1033\fs24 .
