\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 (\plain \f1\lang1033\fs24 Im Kopfsteg\plain \f1\lang1033\fs22 )\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Johannes Wallman\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 1{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nomen secundum modistas est pars oracionis significans per modum habitus et quietis}}\plain \f1\i\lang1033\fs24  et per modum determinate apprehensionis \plain \f1\lang1033\fs24 (vgl. Thomas de Erfordia, Grammatica speculativa, \u167 \'a7 16, ed. \plain \f1\scaps\lang1033\fs24 Bursill-Hall\plain \f1\lang1033\fs24 , S. 154). \endash  \plain \f1\i\lang1033\fs24 Nomen secundum Priscianum est pars oracionis que unicuique subiectorum corporum\plain \f1\lang1033\fs22  \u8230 \'85\plain \f1\lang1033\fs24  \endash  \plain \f1\super\lang1033\fs24 2{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nomen numerale est diccio importans et est duplex, scilicet ordinale et cardinale}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Omnia nomina numeralia cardinalia sunt pluralis numeri\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Wersus: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 A tribus usque centum tibi do tale documentum}}\plain \f1\i\lang1033\fs24 : Sunt omnis generis, pluralia nec variabis\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 \par}

