\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (151\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) Inhalts\u252 \'fcbersicht. \endash  (152\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -154\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Prolog: [{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 D]iligite iusticiam (Sap 1,1). Audite hoc omnes gentes (Ps 48,2). Audite, inquam, et percipite auribus}}\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (154\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -180\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Text: [{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 U]trum constitui redditus pecuniarum uel aliarum rerum}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85\plain \f1\i\lang1033\fs24 que tamen non sunt humano iure particulariter\plain \f1\lang1033\fs24 || [expresse prohibita]. Textabbruch, BSB-Ink G-182, Bd. 4, Bl. CCLII\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Z. 5.
