\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 C\u8249 \'8bum aduersus sanctam sinodum Basiliensem vniuersalem ecclesiam representantem}}\plain \f1\i\lang1033\fs24  nonnulli diebus istis\plain \f1\lang1033\fs24  - \plain \f1\i\lang1033\fs24 proh dolor\plain \f1\lang1033\fs24  - \plain \f1\i\lang1033\fs24 predicte sinodo non solum debito religionis christiane\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 in illius pretensi parui decreti detestacionem oremus oretenus fuerant promulgata et postea in scriptis redacta\plain \f1\lang1033\fs24  (zwischen 1.-9. Oktober1440).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
