\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 301\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -302\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Super consultatione archiepiscopi Salisburgensis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Super consultacione Reuerendissimi in Christo patris et domini, domini Archiepiscopi Salczeburgensis necnon apostolice sedis legati deliberacio et consilium studii Wiennensis\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In primis dicimus, quod quantum de iure et de facto hucusque noscere potuimus}}\plain \f1\i\lang1033\fs24 , non est nobis aliud visum quam quod sacrum generale Basiliense concilium sit legittime\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 quam in dietis fiunt aut factam sunt, auctoritate carent nec aliquem christianum iuris ligare possunt ad presens in sacro Basiliensi concilio, cum nec ipsum transferri possit eo nolente nec aliud institui queat eo existente\plain \f1\lang1033\fs24  (14. M\u228 \'e4rz 1442). \endash  302\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Auch u.d.T. \plain \f1\i\lang1033\fs20 Responsum facultatis theologicae studii Viennensis pro concilio Basiliensi\plain \f1\lang1033\fs20 . Gutachten der Wiener Universit\u228 \'e4t zugunsten der Rechtm\u228 \'e4\u223 \'dfigkeit und Fortf\u252 \'fchrung des Basler Konzils. \endash  Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cgm 1586}}\plain \f1\lang1033\fs20 , 108\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -109\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; Olm\u252 \'fctz, Wiss. SB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M I 356}}\plain \f1\lang1033\fs20 , 58\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -61\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; Wien, \u214 \'d6NB, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 cvp 4957}}\plain \f1\lang1033\fs20 , 88\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -89\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ; Wien, Schottenstift, StiftsB, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. 74}}\plain \f1\lang1033\fs20 , 220\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -222\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 .}

