\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Glo\plain \f1\lang1033\fs24 [sa] \plain \f1\i\lang1033\fs24 super illa Cle\plain \f1\lang1033\fs24 [mentina]. \endash  \plain \f1\i\lang1033\fs24 De summa trinitate. Compilata per dominum Nicolaum Siculum Maniacensis abbatem dignissimum, nunc vero archiepiscopum Panormitanum\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod statim tempore concepcionis Christus fuit perfectus homo}}\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 et qualis et qualiter gracia infundatur in baptismate, vide ad predicta glo\plain \f1\lang1033\fs24 [sa] \plain \f1\i\lang1033\fs24 in dicta Cle\plain \f1\lang1033\fs24 [mentina] \plain \f1\i\lang1033\fs24 i. in vero virtutes cum se. Et tantum\plain \f1\lang1033\fs24 .
