\pard\keep\keepn\fi0\li0\ql\ri0\sb195\sa0\itap0 \plain \f1\lang1033\fs24 175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Henricus Toke}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De ecclesia militante catholica cum dialogo}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 In nomine domini\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 nostri Ihesu Christi. Amen. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Queritur, an ecclesia militans Catholica sancta et immaculata sit}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 singulariter approbet et confirmet pro reformacione ecclesie ac edificacione ad gloriam omnipotentis dei, domini nostri Ihesu Christi, qui cum patre\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 . \endash  (207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Sequitur vtilis dyalogus pro solucione dubiorum occurrencium circa premissa. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Contra premissa multipliciter obiectum est et primo contra notabile primum dicit opponens}}\plain \f1\i\lang1033\fs24 : Cur negas papam esse antichristum\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 sit benedictus dominus deus\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 per dominum nostrum Ihesum Christum, qui cum eodem deo patre et spiritu sancto viuit et regnat trinus et vnus in sempiternum. Amen\plain \f1\lang1033\fs24 . \endash  221\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
