\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 D\u8249 \'8bEus in adiutorium meum intende (Ps 69,2). Excelsus ille propheta Dauid, de quo scriptum nouimus}}\plain \f1\i\lang1033\fs24\cf1 , deum dixisse, quod invenit hominem secundum cor suum\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 vt veritatem amplectentes per ipsum, qui via est, perveniamus ad vitam gracie in presenti et glorie in futuro. Amen. Et tantum de illo articulo\plain \f1\lang1033\fs24\cf1 .
