\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 I\u8249 \'8bVdex debet citare partem ad requisicionem illius, qui conqueritur}}\plain \f1\i\lang1033\fs24 . Probatur in Auten\plain \f1\lang1033\fs24 [tico], \plain \f1\i\lang1033\fs24 De man\plain \f1\lang1033\fs24 [datis] \plain \f1\i\lang1033\fs24 prin\plain \f1\lang1033\fs24 [cipum], \plain \f1\i\lang1033\fs24 \u167 \'a7 Quo non promittente. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item judex debet precipere seruienti, quod ex parte sua citet eum}}\plain \f1\i\lang1033\fs24  ad instanciam talis vt tali die compareat coram eo\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 vel homicida non potest saluari in ecclesia auctoritate, De manda\plain \f1\lang1033\fs24 [tis] \plain \f1\i\lang1033\fs24 prin\plain \f1\lang1033\fs24 [cipum] \plain \f1\i\lang1033\fs24 circa fi\plain \f1\lang1033\fs24 [nem] (C. 1.15.un.) \plain \f1\i\lang1033\fs24 et C. De hiis qui ad ecclesiam confugi\plain \f1\lang1033\fs24 [unt], \plain \f1\i\lang1033\fs24 l. ii in glos\plain \f1\lang1033\fs24 [a] (C. 1.12.2). \plain \f1\i\lang1033\fs24 Et sic est finis presentis tractatus\plain \f1\lang1033\fs24 .
