\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Parallel\u252 \'fcberlieferung: Eichst\u228 \'e4tt, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. st 266}}\plain \f1\lang1033\fs20 , 106\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -107\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  (wohl unvollst\u228 \'e4ndig); L\u252 \'fcneburg, Ratsb\u252 \'fccherei, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Jurid. E 2\u176 \'b0 11}}\plain \f1\lang1033\fs20 , 70\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 -74\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20 ; Vatikanstadt, BAV, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. lat. vat. 5923}}\plain \f1\lang1033\fs20 , 71\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20 -74\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 . \endash  Das Repertorium umfasst 195 Casus. Neben den h\u228 \'e4ufig zitierten Autorit\u228 \'e4ten Johannes Andreae und Guido de Baisio (Archidiaconus) werden auch Zenzelinus de Cassanis (368\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  Z. 21, 369\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  Z. 17; s. Bio-Bibliographical Guide, Report No. r327) und Simon de Borsano (372\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  Z. 24, s. Bio-Bibliographical Guide, Report No. r533) genannt.}

