\par \pard\fi0\li0\tx12825\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Svm[m]a preceptorum ad eandem partem composicionis superioris}}\plain \f1\i\lang1033\fs24  pertinentium, que ad ordinem et collocacionem verborum spectant, quod se oracio augeat\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 a summis poetis aut oratoribus fuit recepta\plain \f1\lang1033\fs24 . \endash  Mit Zusatz: \plain \f1\i\lang1033\fs24 Hoc inter cum et tum refert et tum duplicatum ut multis locis admonet Cicero\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 in hoc exemplo Cicero tum natura tum consuetudine ad omnes res honestas flammato studio rapiebatur. Amen.
\par \pard\fi0\li0\tx12825\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
