\par \pard\fi0\li0\tx12825\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24\cf1 Incommoda senectutis. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Si quis ad senectutem processerit}}\plain \f1\i\lang1033\fs24\cf1 , statim corpus\plain \f1\lang1033\fs24\cf1  (!, vielm. cor) \plain \f1\i\lang1033\fs24\cf1 eius affligitur\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 vituperat presens, laudat preteritum\plain \f1\lang1033\fs24\cf1 .
