\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 252\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -254\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistolae}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1 (252\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Quantum recommendationes tue pro me valuerint}}\plain \f1\i\lang1033\fs24\cf1  apud egregium virum Nicolaum\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1 (\plain \f1\lang1033\fs24 252\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nihil ex hiis, que mihi scribis, noui presencio}}\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (252\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Si pecunie, quas a vobis suscepi causa sumptum}}\plain \f1\i\lang1033\fs24 , qui suppeditant, in re familiari cicius consumpte sunt\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 (252\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod tu, velut scribis, consumpte sunt pecunie}}\plain \f1\i\lang1033\fs24  nondum adduci possum\plain \f1\lang1033\fs24  \u8230 \'85\endash  \plain \f1\super\lang1033\fs24 5\plain \f1\lang1033\fs24 (252\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Si vales bene est ego, quid valeo totaque mecum domus mea valet}}\plain \f1\i\lang1033\fs24 , tuas maxime quidem litteras expectabam\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 6\plain \f1\lang1033\fs24 (252\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Et si neque tibi neque ceteris amicis meis probata sit}}\plain \f1\i\lang1033\fs24  mei animi sentencia\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 7\plain \f1\lang1033\fs24 (252\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quo in statu sint nostre res}}\plain \f1\i\lang1033\fs24 , ex hoc potes cognoscere\plain \f1\lang1033\fs24  \u8230 \'85 (auch: Vatikanstadt, BAV, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. lat. vat. 5197}}\plain \f1\lang1033\fs24 , 61\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). \endash  \plain \f1\super\lang1033\fs24 8\plain \f1\lang1033\fs24 (253\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod res mee iniquo sint loco posite}}\plain \f1\i\lang1033\fs24 , non meo tantam abstulit animo perturbacionem\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 9\plain \f1\lang1033\fs24 (253\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Plura tibi committerem, si mihi tuus magis cognitus}}\plain \f1\i\lang1033\fs24  esset amicus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 10\plain \f1\lang1033\fs24 (253\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Magnam percepi voluptatem, filii dilecte}}\plain \f1\i\lang1033\fs24 , ex hiis, que mihi de te narrari perseuera\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 11\plain \f1\lang1033\fs24 (253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod ex hiis, que vobis de}}\plain \f1\lang1033\fs24  (korr. aus debeo) \plain \f1\i\lang1033\fs24 me notificantur, gratam percipiatis voluptatem et letor et gaudeo perseueraboque\plain \f1\lang1033\fs24  \u8230 \'85\endash  \plain \f1\super\lang1033\fs24 12\plain \f1\lang1033\fs24 (253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Spectabilis et egregie, mi domine ac mi pater venerande}}\plain \f1\i\lang1033\fs24 , nisi longa vobis experiencia persuasum esse credere\plain \f1\lang1033\fs24  \u8230 \'85\endash  \plain \f1\super\lang1033\fs24 13\plain \f1\lang1033\fs24 (253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Etsi me non lateat neminem ita subducta ratione viuere}}\plain \f1\lang1033\fs24  \u8230 \'85\endash  \plain \f1\super\lang1033\fs24 14\plain \f1\lang1033\fs24 (254\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Constitui Johannes, mi carissime, velle moribus illis}}\plain \f1\i\lang1033\fs24  sic finem facere\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 15\plain \f1\lang1033\fs24 (254\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod aliud vite genus sequi constitueris}}\plain \f1\i\lang1033\fs24 , ita et probo et laudo\plain \f1\lang1033\fs24  \u8230 \'85. \endash  \plain \f1\super\lang1033\fs24 16\plain \f1\lang1033\fs24 (254\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tuas litteras pridem accepi, quibus ex me scire}}\plain \f1\i\lang1033\fs24 , quid de illa tua absolucione sententiam plurimum desideras\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 salutes ex mei parte dominum Iacobum, dominam quam Catherinam, Michaelem et nostros ibi necessarios existentes. Vale feliciter\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Sammlung von 16 \u220 \'dcbungs- und Musterbriefen ohne Anrede, Ort und Datum. \endash  \plain \f1\scaps\lang1033\fs20 Bertalot\plain \f1\lang1033\fs20 , IHL 2,2 Nr. 17815 (Hs. genannt). \endash  Parallel\u252 \'fcberlieferung (ep. 1-15): San Gimignano, Biblioteca Comunale, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Ms. 27}}\plain \f1\lang1033\fs20 , 52\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -54\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ; vgl. Inventari dei manoscritti delle biblioteche d'Italia 88: S. Gimignano, Biblioteca Comunale, acura di Giuseppe \plain \f1\scaps\lang1033\fs20 Mazzatinti\plain \f1\lang1033\fs20 , Albano \plain \f1\scaps\lang1033\fs20 Sorbelli\plain \f1\lang1033\fs20  u.a. Florenz 1972, S. 121f.}

