\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 254\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -257\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gasparinus Barzizius}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Epistolae}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (254\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Casparinus Pergamensis plurimam dicit salutem. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gaudeo plurimum te in hac sententia esse}}\plain \f1\lang1033\fs24  \u8230 \'85\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (\plain \f1\scaps\lang1033\fs24 Mazzuconi\plain \f1\lang1033\fs24  Nr. 89). \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (255\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Casparinus Pergamensis Danieli suo multam salutem dicit. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod Andreas noster assumptus sit ad questuram}}\plain \f1\lang1033\fs24  \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Bertalot\plain \f1\lang1033\fs24 , S. 69f. Nr. 17; \plain \f1\scaps\lang1033\fs24 Mazzuconi\plain \f1\lang1033\fs24  Nr. 227). \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (255\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sepius ad te scriberem, Daniel suauissime}}\plain \f1\i\lang1033\fs24 , nisi ea te constancia preditum esse cognoscemus\plain \f1\lang1033\fs24  \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Mazzuconi\plain \f1\lang1033\fs24  Nr. 268). \endash  \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 (255\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Casparinus de Barziziis nobili et egregio viro domino Danieli Victurio, fratri carissimo. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Etsi acerbum sit genus consolacionis}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Furietti\plain \f1\lang1033\fs24 , S. 196f.; \plain \f1\scaps\lang1033\fs24 Sabbadini\plain \f1\lang1033\fs24 , S. 372 Nr. 35; \plain \f1\scaps\lang1033\fs24 Mazzuconi\plain \f1\lang1033\fs24  Nr. 54). \endash  \plain \f1\super\lang1033\fs24 5\plain \f1\lang1033\fs24 (256\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quantam ex litteris tuis perceperim voluptatem Andrea, mi carissime}}\plain \f1\i\lang1033\fs24 , ex hoc potes intelligere\plain \f1\lang1033\fs24  \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Mazzuconi\plain \f1\lang1033\fs24  Nr. 206). \endash  \plain \f1\super\lang1033\fs24 6\plain \f1\lang1033\fs24 (257\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Optatas tuas accepi litteras de manu cuiusdem}}\plain \f1\i\lang1033\fs24  non satis mihi noti\plain \f1\lang1033\fs24  \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Bertalot\plain \f1\lang1033\fs24 , S. 64f. Nr. 11). \plain \f1\i\lang1033\fs24 Leonhardus Aretini ad Petrum istum\plain \f1\lang1033\fs24 || wohl Textabbruch.
