\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 168\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -179\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Commentum in Summulas logicales Petri Hispani (Tract. III)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Prolog: \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Benedictus deus, qui totam naturam fecit sub proprietatibus decentibus}}\plain \f1\i\lang1033\fs24  ob salutem humani generis eidemque nature indidit oc\plain \f1\lang1033\fs24 [c]\plain \f1\i\lang1033\fs24 ultas intentiones et similtudines\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b \plain \f1\i\lang1033\fs24 Admirans ergo creaturam et non admirans creatorem ipsius creature similis est illi, qui litteras aureas aspicit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Circa igitur prohemialem accessum predicamentorum mouetur hec questio\plain \f1\lang1033\fs24 , [u]\plain \f1\i\lang1033\fs24 trum\u8249 \'8b\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 de predicamentis sit sciencia\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (169\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ad cognoscendum predicamenta\u8249 \'8b (\u167 \'a7 1). Iste est tractatus tercius, qui continuatur ad precedentem sic}}\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 In precedenti trac\plain \f1\lang1033\fs24 [ta]\plain \f1\i\lang1033\fs24 tu de racionibus, quibus ordinabilia ordinantur in genere, determinatum est. Nunc consequenter agendum est de ordinamentis in genere sub huiusmodi racionibus\plain \f1\lang1033\fs24  \u8230 \'85 \endash \u8230 \'85 \plain \f1\i\lang1033\fs24 eo quod non est ordinabile in uno genere sed in pluribus. Et hec de presenti leccione. Et per consequens de isto toto tercio tractatu sufficiant de predicamentis et aliis bonis dictis\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 179\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -185\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Commentum in libros Peri hermeneias Aristotelis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 De radicali intellectu ante praedicamentorum omnia\u8249 \'8b Dici est actus vocis}}\plain \f1\i\lang1033\fs24  ad intelligi\plain \f1\lang1033\fs24  (!, vielm. intelligendum) \plain \f1\i\lang1033\fs24 res. Intellectio rei sistit primo in esse et subsequenter in re participante esse\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et in hoc terminatur recapitulatio fundamentalium enumeracionum in certo ordine cum radicalibus probacionibus duorum librorum periarmenarum Aristotelis\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 185\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -190\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Commentum in Summulas logicales Petri Hispani (Tract. IV)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (185\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iste est tractatus quartus Petri Hispani, in quo determinatur de sillogismo simpliciter}}\plain \f1\i\lang1033\fs24  et ordo eius ad tres precedentes tractatus est iste, quia primus tractatus respicit secundam operacionem intellectus\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Diuiditur autem in generali iste totus tractatus quartus in tres partes principales. In prima parte determinatur de constructione sillogismi ostendendo uidelicet quomodo sillogismus principiis suis tam formalibus quam materialibus principietur\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\i\lang1033\fs24 Circa materiam huius textus mouetur hec questio\plain \f1\lang1033\fs24 . (185\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Questio\plain \f1\lang1033\fs24 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 utrum sillogismus simpliciter, qui est subiectum huius tractatus, sid (!) sciencie principiatus}}\plain \f1\i\lang1033\fs24  materialiter proposicione\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ad tertiam propositum est in supposicione vna consequens elementi manente. Et hec de presenti de quarto tractatu sufficient\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 190\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -192\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De discursibus syllogismorum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Capitulum de origine, necessitate ac vtilitate discursuum sillogismorum\plain \f1\lang1033\fs24  \u8230 \'85 \u8249 \'8b [{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 A]ristotele attestante primo Metaphysice et in fine primi posteriorum principium}}\plain \f1\i\lang1033\fs24  nostre cognicionis est a sensu non tamquam a causa sufficienti et totali sed magis quodammodo quasi materia causa est\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 per conuersionem intellectus ad fantasmata, que sunt in viribus sensitiuis. Et hec de capitulo\plain \f1\lang1033\fs24 . \endash  (192\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kolophon}}\plain \f1\lang1033\fs24  mit Angabe von Studienzeiten einschlie\u223 \'dflich Rezept f\u252 \'fcr eine studienf\u246 \'f6rdernde Salbe: \plain \f1\i\lang1033\fs24 Ego Iohannes theologus vtriusque iuris doctor ordinis sancti Augustini indignus canonicus secularis\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Modus studendi talis est: Nocte sis quietus ita quod modicum, ideo sero post cenam}}\plain \f1\i\lang1033\fs24 , procedas mane, quando surrexeris, jeiunes usque ad uesperas bene sumendo haustum vini albi uel senioris cereuisie et hoc ante ver circa horam meridiei\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Post uesperas habeas aquam artificialem factam de ruta ex plantagine, cum quasi facies locionem capitis usque ad venarum limporum rubefactionem\plain \f1\lang1033\fs24  \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Confectio ungenti fit hoc modo: Recipe flores medicorum proprie Haydelbluomen}}\plain \f1\i\lang1033\fs24 , Mellisma\plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24 proprie mater uel mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ter, Satureyam, Hartkumich partes equales\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 et pone in uase uitrio cum oleo oliuarum recente per decem dies ad solem\plain \f1\lang1033\fs24  \u8230 \'85 \endash  mit Fortsetzung auf 196\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Tunc vtendum est quatuor temporibus scilicet Martini, Philippi, Blasii, Bartholomei. Post unccionem statim cooperias capud tuum cum aliqua re, ita tamen quod aer sinistrias\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 non ingrediatur poros capitis\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Et testator hoc doctor subtilis Scotus et durat vngentum ad duos annos in plena sua virtute\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Deo gracias\plain \f1\lang1033\fs24 .}

