\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 192\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -196\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Commentum in Summulas logicales Petri Hispani (Tract. V)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b[{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 R]acio multis modis\u8249 \'8b (\u167 \'a7 1). Iste est tractatus quintus, in quo de argumento confirmato per locum}}\plain \f1\i\lang1033\fs24  quomodo\plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24 argumentum dicitur sillogismus probabilis. Et quia argumentum confirmatum per locum est subiectum huius sciencie. Ideo secundum duo, que sunt in isto subiecto, diuisus est iste totus quintus tractatus in duas partes principales\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Circa presentem textum\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 ipsius argumenti movetur hec\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Questio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 utrum tantum quatuor sunt species argumentacionis enumerate in textu scilicet sillogismus, induccio, enthimema, exemplum\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 que tanguntur noster Petrus Hispanus quo ad distribuciones et subkathegoreumam et fallacias, summatim continentur in copia sophismatum\plain \f1\lang1033\fs24  [et]\plain \f1\i\lang1033\fs24  ibidem habeantur recursus\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 197\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -205\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Commentum in Analytica priora Aristotelis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Capitulum ostendens communem animi concepcionem libri priorum}}\plain \f1\i\lang1033\fs24  que in fecunditate sua prehabet omnes conclusiones totius noue logice. Ex hoc, quod omnes sillogismi ordinantur ad scienciam demonstratiuam ingerendam sicut in finem intentum, ut tollitur ex inicio libri priorum, in quo dicit Aristoteles\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Quoniam circa demonstrationem et de disciplina demonstratiua\plain \f1\lang1033\fs24  (An. prior. 24a10). \plain \f1\i\lang1033\fs24 Tria est intencio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ad tria disponenda est secundum exigentiam forme inducende. Materia autem sillogismi est propositio\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 numquam tamen refert ipsam disposicionem absolute ad ista nomina sicut res scilicet modus rei et dispositio, relacio autem est recordacio rei antelate\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 205\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -207\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Cautelae ad Metaphysicam Aristotelis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Hic incipiunt cautele\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 ad ducendum aliquod ad metaphysicam. Et primo ad methaphysicam falsus et inopinabilis\plain \f1\lang1033\fs24 . \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Falsum autem in aliquo\u8249 \'8b (Soph. el. 172b10). Iste est quartus tractatus, in quo Aristoteles determinat de cautelis}}\plain \f1\i\lang1033\fs24 , per quas opponens zophista sit captus\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Et diuiditur iste tractatus in quattuor capitula. In primo capitulo dat philosophus quinque cautelas ad concludendum falsum et inopinabile coniuncti\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 si respondens ipse uiderit aliquod inconueniens sequi suam posicionem, debet illud dicere ne opponens sibi proponat\plain \f1\lang1033\fs24 . \endash  207\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

