\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 207\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -210\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Quaestio de limitatione praedicamentali}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Utrum deus sit in predicamento vbi dicunt antiqui, quod non / moderni, quod sic}}\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Pro questione illa notandum \plain \f1\lang1033\fs24 [est],\plain \f1\i\lang1033\fs24  quod secundum Auicennam et doctorem sanctum omnia et sola illa sunt in genere predicamentali\plain \f1\lang1033\fs24  \u8230 \'85\endash  (208\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Conclusio prima\plain \f1\lang1033\fs24 \u8249 \'8b, \plain \f1\i\lang1033\fs24 quod deus ut genus in predicamento non est ponendus\plain \f1\lang1033\fs24  \u8230 \'85\endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Secunda conclusio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Deus ut species in nullo genere principali est ponendus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (208\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Tertia conclusio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Deus ut differencia in genere non est ponendus\plain \f1\lang1033\fs24  \u8230 \'85\endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Quarta conclusio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Deus ut indiuiduum non est in aliquo genere ponendu\plain \f1\lang1033\fs24 s \u8230 \'85\endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Quinta conclusio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Deus in genere predicamentali nullo potest collocari\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (208\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -210\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Contra conclusionem sic arguo primo\plain \f1\lang1033\fs24 \u8249 \'8b (mit f\u252 \'fcnf Gegengr\u252 \'fcnden der Via moderna) \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 quid est in hac vita de substantiis simplicibus\plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24 principalissime de deo aliquid cognoscere\plain \f1\lang1033\fs24 . \endash  210\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -210a\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  leer.}

