\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 (Bl. 211-232) Wasserzeichen: Ochsenkopf, Abb. s. WZIS DE5580-Clm6704_222/226. \endash  Lagen: VI\plain \f1\super\lang1033\fs20 222\plain \f1\lang1033\fs20  + (VI-2)\plain \f1\super\lang1033\fs20 232\plain \f1\lang1033\fs20 ; (222\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) Wortreklamante. \endash  Schriftraum: 24-25,5 \u215 \'d7 15,5-16; zweispaltig; 51-52 Zeilen. \endash  {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Semihybrida Currens}}\plain \f1\lang1033\fs20  von einer Hand (Hand 6). (211\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -212\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 ) Rubriziert.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 211\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -215\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Quaestiones super Isagogen Porphyrii}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Utrum sciencia quinque predicabilium necessaria sit ad quatuor a Por[p]hirio assignata}}\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Videtur quod non, quia sunt posteriora illis quatuor, ergo non sunt neccessaria in oppositum. Sciendum, quod in acquisicione scienciarum vtitur intellectus triplici instrumento, scilicet diuisione, diffinitione, demonstracione\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 vnde quale\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 hic capitur aliter in diuisione quantitatis sicut ibi patebit\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kolophon}}\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Et sic est finis. Expliciunt predicabilia Porphirii. Incipiunt predicamenta Aristotelis. Deus laudetur\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 216\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -223\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Quaestiones in librum Praedicamentorum Aristotelis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Queritur, utrum de decem predicamentis sit sciencia, cuius subiectum est ens}}\plain \f1\i\lang1033\fs24  dicibile incomplexum ordinabile in genere secundum sub et supra prout stat sub uoce talem ordinem signante, videtur quod non\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 quia in hac sciencia non est agendum nisi de hiis modis, que reperiuntur in coordinacione rerum predicamentalium. Et sic est finis. Expliciunt praedicamenta Aristotelis. Incipit liber primus periarmeneiarum\plain \f1\lang1033\fs24 .
