\par \pard\fi0\li0\tx12825\ql\ri0\sb0\sa0\itap0 \plain \f1\super\lang1033\fs24 130\plain \f1\lang1033\fs24 (329\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -331\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Manducabitis panem (I Cor 11,26). Venerandi patres, magistri, domini, inquit beatus Jeronimus super hoc ecclesiastices}}\plain \f1\i\lang1033\fs24 , quia hoc solum habemus in presenti seculo bonum\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs24\cf1 \u8230 \'85\endash  (329\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  Z. 41) Hauptteil: \plain \f1\i\lang1033\fs24\cf1 Manducabitis\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24\cf1 Inquit beatus Ambrosius in canone De cons\plain \f1\lang1033\fs24\cf1 [ecratione], \plain \f1\i\lang1033\fs24\cf1 di\plain \f1\lang1033\fs24\cf1 [stinctio] \plain \f1\i\lang1033\fs24\cf1 ii\plain \f1\lang1033\fs24\cf1  (De cons. D.2 c.14) \plain \f1\i\lang1033\fs24\cf1 et allegatur per magistrum sentenciarum\plain \f1\lang1033\fs24\cf1 , \plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ut non indignos reiciat, sed in eternitate nos beatifice conducat et collocat. Quid nobis prestare dignetur\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 131\plain \f1\lang1033\fs24 (332\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -338\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ihesus. \plain \f1\lang1033\fs24 Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cepit lauare (Io 13,5). Dominus et saluator noster Ihesus Christus eterni patris sapiencia}}\plain \f1\i\lang1033\fs24 , xxxviii di\plain \f1\lang1033\fs24 [stinctio] \plain \f1\i\lang1033\fs24 in c.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Si iuxta apostolum\plain \f1\lang1033\fs24  (D.38 c.9), \plain \f1\i\lang1033\fs24 mysteriis maxime humilitatis exemplum commendatur\plain \f1\lang1033\fs24  \u8230 \'85\endash  (332\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Z. 16) Hauptteil: \plain \f1\i\lang1033\fs24 Secundum sententiam beati Augustini in quodam sermone presentis festiuitatis diuina sapiencia de sinu eterni patris egressa\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 qui hodie discipulorum cepit lauare pedes, quod nobis prestare dignetur eternus pater. Amen\plain \f1\lang1033\fs24 . \endash  339\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -340\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\tx12825\ql\ri0\sb0\sa0\itap0 
