\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -VII\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer. \endash  (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Sermo 2: \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 H\u8249 \'8bomo quidam fecit \u8230 \'85 (Lc 14,16). Postillam ewangelii huius require dominica}}\plain \f1\i\lang1033\fs24  2\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Notandum, quod ut docet magister 2\u176 \'b0 sententiarum distinctione prima: Deus a principio hominem ad hoc creauit\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (4\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Sermones 8-9. \endash  (6\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  Z. 11) Sermo 10: \plain \f1\i\lang1033\fs24 Consequenter est dicendum de Inuidia. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nunc de Inuidia dicendum est, que licet secundum Gregorium}}\plain \f1\i\lang1033\fs24  31 Moralia sit vicium capitale\plain \f1\lang1033\fs24  \u8230 \'85 (Textanfang auch in: Augsburg, SuStB, 4\u176 \'b0 Cod 51, 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; Stuttgart, WLB, HB I 209, 50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). \endash  (8\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Sermo 11. \endash  (11\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Sermo 7: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dictum est prius de superbia et aliquibus viciis}}\plain \f1\lang1033\fs24  \u8230 \'85 (Textanfang auch in: Eichst\u228 \'e4tt, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. st 219}}\plain \f1\lang1033\fs24 , 331\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ; Frankfurt, StUB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ms. lat. qu. 50}}\plain \f1\lang1033\fs24 , 217\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ; Gie\u223 \'dfen, UB, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs. 766}}\plain \f1\lang1033\fs24 , 166\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; M\u252 \'fcnchen, UB, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 2\u176 \'b0 Cod. ms. 57}}\plain \f1\lang1033\fs24 , 252\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ; Stuttgart, WLB, {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 HB I 195}}\plain \f1\lang1033\fs24 , 96\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ). \endash  (20\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Sermones 12-17.
