\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (228\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Prologus\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24 Tabula\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Pro tabula exposicionis symboli apostolorum est sciendum, quod totus liber est distinctus in xiii partes, videlicet in prologum et xii articulos\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (232\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequitur prologus exposicionis Symboli apostolorum magistri Johannis Mayrenwerder\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 venerabilis doctoris studii Pragensis\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 U\u8249 \'8benite ambulemus (Is 2,5). Qui volumus, ut debemus in fide credibilium proficere per verba}}\plain \f1\i\lang1033\fs24  assumpta\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (240\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit exposicio Symboli Apostolorum magistri Johannis Mayrenwerder venerabilis doctoris Studii Pragensis\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24 Articulus primus\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 C\u8249 \'8bredo in deum patrem omnipotentem \u8230 \'85 In hoc symbolo fides benedicte trinitatis Christi domini nostri deitatis}}\plain \f1\i\lang1033\fs24  et humanitatis exprimitur \plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 qui stas in littore\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 celestis patrie me exspectans per Ihesum Christum dominum nostrum saluatorem omnium, qui tecum viuit et regnat\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen. Et sic est finis\plain \f1\lang1033\fs24 . \endash  309\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -311\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
