\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 172\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -180\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones de BMV}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 De beata virgine Maria\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 T\u8249 \'8bransite ad me (Sir 24,26). Notandum, quod virgo quinque vias transiuit}}\plain \f1\i\lang1033\fs24 . Transiuit enim viam castitatis, paupertatis, humilitatis, amaritatis et eterne beatitudinis\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 de spiritu sancto exaltata est in mundo et in celo super omnes choros angelorum et per gloriam et honorem. Psalmus: Astitit regina a dextris tuis\plain \f1\lang1033\fs24  (Ps 44,10). \endash  (173\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Franciscus de Maironis\plain \f1\lang1033\fs24 : \u8250 \'9b\plain \f1\i\lang1033\fs24 De Assumpcione v\plain \f1\lang1033\fs24 [irginis] \plain \f1\i\lang1033\fs24 M\plain \f1\lang1033\fs24 [arie]\u8249 \'8b \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 A\u8249 \'8bd preceptum tuum (Iob 39,27). Quia uero mater domini in sua assumpcione fuit exaltata}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ad istam ciuitatem nos perducat Christus, filius eius, qui cum patre\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 2, S. 75 Nr. 133; ferner 3, S. 132 Nr. 950 (\plain \f1\scaps\lang1033\fs24 Jacobus de Lausanna\plain \f1\lang1033\fs24 ); 4, S. 587 Nr. 57, 158 (\plain \f1\scaps\lang1033\fs24 Petrus Aureoli\plain \f1\lang1033\fs24 ). \endash  (175\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Radulphus de Escuris\plain \f1\lang1033\fs24 : \u8250 \'9b\plain \f1\i\lang1033\fs24 Idem\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 I\u8249 \'8bntrauit Ihesus in quoddam castellum (Lc 10,38). Omelia beati Anshelmi de eodem leccione. In sacra scriptura res vna et eadem multociens invenitur}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 precibus eius per Ihesum Christum, filium eius, qui viuit\plain \f1\lang1033\fs24  \u8230 \'85 Druck: PL 95, 1505-1508; PL 158, 644-649; Andr\u233 \'e9 \plain \f1\scaps\lang1033\fs24 Wilmart\plain \f1\lang1033\fs24 , Les hom\u233 \'e9lies attribu\u233 \'e9es \u224 \'e0 saint Anselme, in: Archives d'histoire doctrinale et litt\u233 \'e9raire du Moyen \u194 \'c2ge 2 (1927), S. 5-29, 339-341, hier S. 16-23 (zum Verfasser); daran (176\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  Z. 35) \plain \f1\scaps\lang1033\fs24 Bernhardus Claraevallensis\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Et consequitur ex omelia beati Bernardi. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Et quis in die assumpcionis eius in ecclesiis Christi leccio ewangelica recitatur}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 vtrobique amplectenda dignacio maiestatis\plain \f1\lang1033\fs24 . Druck: PL 183, 416f. \endash  (176\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Johannes Contractus\plain \f1\lang1033\fs24 : \u8250 \'9b\plain \f1\i\lang1033\fs24 De beata virgine\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 H\u8249 \'8bodie magnificata est (Idt 12,18). Verbum istud potuit dicere beata Maria virgo}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ad eterna gaudia peruenire mereamur, quod nobis concedat\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 3, S. 442 Nr. 121. \endash  (178\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De natiuitate v\plain \f1\lang1033\fs24 [irginis] \plain \f1\i\lang1033\fs24 M\plain \f1\lang1033\fs24 [ariae]\u8249 \'8b \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 D\u8249 \'8bominus possidet me (Prv 8,22). Quanto aliqua sunt digniora et fini intento proximiora sunt}}\plain \f1\i\lang1033\fs24  preuisione\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 a qua nos meritis eius defendat, qui in trinitate et vnitate perfecta viuit et regnat\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 .}

