\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 184\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -185\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (184\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 I\u8249 \'8bn omnibus operibus (Sir 7,40). Gubernator enim nauis non bene regit nauem, quando diligerit}}\plain \f1\lang1033\fs24\cf1  [et] \plain \f1\i\lang1033\fs24\cf1 respiciat. Sic animus hominis non bene regit uitam ipsius, si nouissima ipsius frequenter non accendat\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 Osee xi: Jugum imponetur ei, quod non aufferetur\plain \f1\lang1033\fs24  (Os 11,7). \endash  \plain \f1\lang1033\fs24\cf1 (184\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) \plain \f1\scaps\lang1033\fs24\cf1 Jacobus de Voragine\plain \f1\lang1033\fs24\cf1 : \plain \f1\i\lang1033\fs24\cf1 De beata virgine\plain \f1\lang1033\fs24\cf1 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Erat nauis in medio mari (Mc 6,47). Sicut dies domini dedicata est dominice resurreccioni}}\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 reconcilians tres status supradictos\plain \f1\lang1033\fs24\cf1  [salvandorum] \plain \f1\i\lang1033\fs24\cf1 ipsi beatissime trinitati\plain \f1\lang1033\fs24\cf1 . \plain \f1\scaps\lang1033\fs24\cf1 Schneyer\plain \f1\lang1033\fs24\cf1 , Repertorium 3, S. 239 Nr. 203. \endash  (185\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Fasciculus mirre (Ct 1,12). Beata virgo Maria in passione Christi multa habuit amaritudines}}\plain \f1\i\lang1033\fs24\cf1 , ideo dicitur: fasciculus mirre\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 quia euaserunt tam horrendum consorcium demonum et assecuti sunt consorcium angelorum. Rogemus dominum\plain \f1\lang1033\fs24\cf1 . \plain \f1\scaps\lang1033\fs24\cf1 Schneyer\plain \f1\lang1033\fs24\cf1 , Repertorium 8, S. 419 Nr. 86.}

