\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 L\u8249 \'8bABERINTVS. }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quid est, vide xxviiii di. c. primo}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  (D.29 c.1)}}\plain \f1\lang1033\fs24 ; \u8250 \'9b\plain \f1\i\lang1033\fs24 L\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 abium. An sit membrum infra v\plain \f1\lang1033\fs24 [ide] \plain \f1\i\lang1033\fs24 Membrum\plain \f1\lang1033\fs24  (s. 48\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -49\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) (Quelle nicht ermittelt). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 L\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 abium. Labia sacerdotis debent scientiam custodire, di. xliiii\plain \f1\lang1033\fs24  (!, vielm. xliii) \plain \f1\i\lang1033\fs24 Si\plain \f1\lang1033\fs24 [t] \plain \f1\i\lang1033\fs24 rector, ante medium\plain \f1\lang1033\fs24  (D.43 c.1) (Druck: Bl. i[5]\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  Z. 25-28). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 L\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 aborator. An laboratores teneantur de turbata possessione\plain \f1\lang1033\fs24  [vide] \plain \f1\i\lang1033\fs24 infra Turbatus\plain \f1\lang1033\fs24  (s. 330\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 et glo\plain \f1\lang1033\fs24 [sa] \plain \f1\i\lang1033\fs24 in l. In Rem \u167 \'a7 Tignum, ff. De rei vendi\plain \f1\lang1033\fs24 [catione] (D. 6.1.23.6) \plain \f1\i\lang1033\fs24 et Bal\plain \f1\lang1033\fs24 [dus] \plain \f1\i\lang1033\fs24 in l. Non ideo, C\plain \f1\b\lang1033\fs24 . \plain \f1\i\lang1033\fs24 De accusa\plain \f1\lang1033\fs24 [tionibus et inscriptionibus] (C. 9.2.5) \plain \f1\i\lang1033\fs24 et\plain \f1\lang1033\fs24  [vide] \plain \f1\i\lang1033\fs24 infra Operarius\plain \f1\lang1033\fs24  (s. 108\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \u8230 \'85 \endash  \u8230 \'85 \u182 \'b6\plain \f1\i\lang1033\fs24 Labor et peccunia diuisione recipiuntur\plain \f1\lang1033\fs24  [vide] \plain \f1\i\lang1033\fs24 supra Com\plain \f1\lang1033\fs24 [m]\plain \f1\i\lang1033\fs24 ode\plain \f1\lang1033\fs24  (s. Clm 6558, 125\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -126\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) (Quelle nicht ermittelt). \endash  (1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 L\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 abor. Vide supra Laborator\plain \f1\lang1033\fs24 . \u182 \'b6\plain \f1\i\lang1033\fs24 Labor bonus est in virtutibus et spiritualibus exerciciis, xxiii q. iii\plain \f1\lang1033\fs24 [i] \plain \f1\i\lang1033\fs24 Quis\plain \f1\lang1033\fs24  [nos] \plain \f1\i\lang1033\fs24 potest\plain \f1\lang1033\fs24  (C.23 q.4 c.43) \u8230 \'85 \endash \u8230 \'85 \u182 \'b6\plain \f1\i\lang1033\fs24 Laborantes pro ecclesia stipendium ab ecclesia recipere debent, xii, q. ii Ecclesiasticis\plain \f1\lang1033\fs24  (C.12 q.2 c.67) (Druck: Bl. i[5]\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  Z. 19-i[6]\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  Z. 6). \endash  (31\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Buchstabe M. \endash  (77\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Buchstabe N. \endash  (96\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Buchstabe O. \endash  (115\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Buchstabe P. \endash  (214\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Buchstabe Q. \endash  (218\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Buchstabe R. \endash  (250\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Buchstabe S. \endash  (307\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Buchstabe T. \endash  (333\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Buchstabe U. \endash  (362\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Buchstabe X. \endash  (362\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Buchstabe Y. \endash  (364\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Buchstabe Z \u8230 \'85 (364\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Z\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 elus. Proprie dicitur amor viri in uxorem, ii q. i\plain \f1\lang1033\fs24  [c.] \plain \f1\i\lang1033\fs24 Si peccauerit in fine\plain \f1\lang1033\fs24  (C.2 q.1 c.19) \u8230 \'85\endash \u8230 \'85 \u182 \'b6\plain \f1\i\lang1033\fs24 Zelo est justicie\plain \f1\lang1033\fs24  (!, vielm. discipline) \plain \f1\i\lang1033\fs24 iusti peccatoribus indignantur, distinctione xlv, c. Vera\plain \f1\lang1033\fs24  [iusticia] (D. 45 c.15) (Druck: Bl. v[3]\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  Z. 28-v[4]\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  Z. 13). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Z\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 ephas. Id est caput uel principium, xx\plain \f1\lang1033\fs24 [ii] \plain \f1\i\lang1033\fs24 distinctione\plain \f1\lang1033\fs24 , [c. ] \plain \f1\i\lang1033\fs24 Sacrosancto\plain \f1\lang1033\fs24  (D.22 c.2) (Quelle nicht ermittelt). \endash  (365\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Z\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 izania. Mixta tritico et crescens cum ipso. Innuit quod in hac vita boni malis mixti sunt\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \u182 \'b6\plain \f1\i\lang1033\fs24 Sinenda sunt utraque crescere usque ad messem judicii extremi et tunc angeli colligent zizania in fasciculos ad comburendum, xxiii q. v c. Ali\plain \f1\lang1033\fs24 [us], \plain \f1\i\lang1033\fs24 \u167 \'a7 1 in finem\plain \f1\lang1033\fs24  (vermutlich C.23 q.1 \u167 \'a7 2) (Druck: Bl. v[4]\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  Z. 14-30). \endash  365\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -365\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
