\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 118\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -121\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes Andreae}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Summa de sponsalibus et matrimonio}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 C\u8249 \'8bhristi nomine inuocato ad honorem ipsius \u8230 \'85 ego Io[hannes] An[dreae] paruus decretorum doctor}}\plain \f1\i\lang1033\fs24  summam breuissimam super quarto\plain \f1\lang1033\fs24  [libro] \plain \f1\i\lang1033\fs24 Decretalium compilaui\plain \f1\lang1033\fs24  \u8230 \'85\endash  (Z. 24) \plain \f1\i\lang1033\fs24 Sponsalia proprie duxit de futuro et duxit futurarum nupciarum promissio\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et non ad propositum vnde quid dicant vide per te\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kolophon}}\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Explicit summula Johannis Andree decretorum doctoris super quarto libro Decretalium xxuiii die mensis Junii anno 1438\plain \f1\lang1033\fs24 . \endash  Rest der Spalte sowie 121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -121d\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 
