\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Angelus de Castro\plain \f1\lang1033\fs24 : \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ihesus. Casus\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In cathedrali ecclesia, in qua sunt canonici regulares habentes prepositum}}\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (32\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quidam scolaris forensis pro alio scolari similiter forensi existente in carcere}}\plain \f1\i\lang1033\fs24  fideiussit \plain \f1\lang1033\fs24 \u8230 \'85 (Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 6661}}\plain \f1\lang1033\fs24 , 257\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -258\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (32\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Franciscus Alvarottus\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 In Christi nomine. Amen. {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quid impertit Velleianum senatus consultum et an Velleiano et Macedoniano renunciari possit}}\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 (36\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Anonymus\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quidam nomine Marsilius habens in bonis valorem octo milia ducatorum}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\scaps\lang1033\fs24 Franciscus de \plain \f1\scaps\lang1033\fs24 Capitibuslist\plain \f1\scaps\lang1033\fs24 e\plain \f1\scaps\lang1033\fs24  et Angelus de Castro\plain \f1\lang1033\fs24 : \plain \f1\super\lang1033\fs24 5\plain \f1\lang1033\fs24 (38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Bertha filia, cum nuptui tradebatur, patri suo Ticio plures filios et filias habenti}}\plain \f1\i\lang1033\fs24  pactum fecit,\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\super\lang1033\fs24 6\plain \f1\lang1033\fs24 (39\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ad fortificandum consilium suprascriptum consuluit Angelus de Castro \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Omissis superfluis videtur michi clarissimum, quod Bertha, de qua in puncto succedere possit \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\scaps\lang1033\fs24 J\plain \f1\scaps\lang1033\fs24 acobus de Zocchis et Federicus de Capitibusliste\plain \f1\lang1033\fs24 : \plain \f1\super\lang1033\fs24 7\plain \f1\lang1033\fs24 (40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ticius, inueniens vxorem suam Bertham cum Gaio eius amatore}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85; \plain \f1\super\lang1033\fs24 8\plain \f1\lang1033\fs24 (41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Consultacioni premisse respondendo dico, quod Gaius irregularitatem incurrit, ut ad sacros promoueri non debeat\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\scaps\lang1033\fs24 Angelus de Castro et F\plain \f1\scaps\lang1033\fs24 e\plain \f1\scaps\lang1033\fs24 dericus de Capitibusliste\plain \f1\lang1033\fs24 : \plain \f1\super\lang1033\fs24 9\plain \f1\lang1033\fs24 (41\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum in sero quidam sacerdos in domo et hospicio communi cenasset}}\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\super\lang1033\fs24 10\plain \f1\lang1033\fs24 (41\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  In casu premisso prima dubitacio est, an sacerdos incurrat irregularitatem ex homicidio commisso \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 11\plain \f1\lang1033\fs24 (42\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 J\plain \f1\scaps\lang1033\fs24 acobus de Zocchis\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum Petrus in differentia esset cum Ticio timeretque ad habitacionem suam propter Ticium}}\plain \f1\i\lang1033\fs24  secure peruenire \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 12\plain \f1\lang1033\fs24 (42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Federicus de Capitibusliste\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ticius quadam nocte transiens per plateas cantando quidam faber obuians ei dicens ei uerba}}\plain \f1\i\lang1033\fs24  iniuriosa\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\scaps\lang1033\fs24 Angelus de Castro\plain \f1\lang1033\fs24 : \plain \f1\super\lang1033\fs24 13\plain \f1\lang1033\fs24 (42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quedam mulier sepius arreptata}}\plain \f1\lang1033\fs24  (!, vielm. arrepta) \plain \f1\i\lang1033\fs24 fuit machinari in mortem mariti sui \plain \f1\lang1033\fs24 \u8230 \'85; \plain \f1\super\lang1033\fs24 14\plain \f1\lang1033\fs24 (43\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Parentes contradixerunt matrimonium per verba de presenti pro filia}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\scaps\lang1033\fs24 Antonius de Rosellis\plain \f1\lang1033\fs24 : \plain \f1\super\lang1033\fs24 15\plain \f1\lang1033\fs24 (43\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Omnipotentis dei postulato suffragio. {\field{\*\fldinst HYPERLINK "hida://5650[16].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Viso processu agitato in nomine spectabilis domine Justine vxoris nobilis}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85; \plain \f1\super\lang1033\fs24 16\plain \f1\lang1033\fs24 (43\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Nota. Casus talis est. {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quidam nobilis laycus habet facultatem participiendi duas partes de omnibus decimis}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 17\plain \f1\lang1033\fs24 (44\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Quaestio\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 YHESVS. {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vtrum possessio acquisita per dominum Franciscum contra dominum Rulandum in Bononia}}\plain \f1\i\lang1033\fs24  habeat sibi in studio Paduano prodesse et ea vti\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 18\plain \f1\lang1033\fs24 (46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Paulus de Castro: Consilium de annuis redditibus\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Casus. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Communitas alicuius terre uel uille de licentia domini sui imposuit}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ut nota ff. Pro socio l. Socium\plain \f1\lang1033\fs24  (D. 17.2.60),\plain \f1\i\lang1033\fs24  qui in eo in principio. Et sic est finis. Et ita consulo ego Paulus de Castro vtriusque iuris doctor\plain \f1\lang1033\fs24  (Druck: GW M30033 = BSB-Ink P-49, Cons. 286, Bl. 158\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -159\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ; Lit.: C\plain \f1\scaps\lang1033\fs24 oing\plain \f1\lang1033\fs24 , Handbuch 1, S. 276, 340; \plain \f1\scaps\lang1033\fs24 Lange/Kriechbaum\plain \f1\lang1033\fs24  2, S. 825f.; vgl. auch die Angaben zu {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 6675}}\plain \f1\lang1033\fs24 , 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 (48\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Controversia de iure sepeliendi
\par \pard\fi0\li0\ql\ri0\sb0\sa60\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (48\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Libellus. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Coram vobis venerabili patre domino etc decano et iudice in spiritualibus ecclesie Salczburgensis dico et propono}}\plain \f1\i\lang1033\fs24 , quod cum anno presenti mense Decembris pie recordacionis Johannes quondam dictus Murawer ex diuina disposicione etc. Et quamquam idem Johannes de iure sepeliri debuerit in dicto monasterio Nunburg\plain \f1\lang1033\fs24  \u8230 \'85\endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (48\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Tenor excepcionis\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (49\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Secuntur allegaciones pro abbatissa contra excepciones predictas\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 (49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Secuntur allegaciones pro abbate\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 5\plain \f1\lang1033\fs24 (50\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Secuntur consilium iurisperitorum de Wienna\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Initien Nr. 2-5 s. Initienregister. \endash  Von Heller fl\u252 \'fcchtig geschriebene Ausz\u252 \'fcge aus einem 1379/1380 ausgetragenen Rechtsstreit zwischen Anna IV. von Liebenberg (\u8224 \'86 1380), \u196 \'c4btissin des Benediktinerinnenstifts Nonnberg, und Otto II. Chalhochsperger (1375-1414), Abt der Benediktinerabtei St. Peter in Salzburg, vor Ortolf von Ovenstetten, seit 1356 Domdekan des Salzburger Domkapitels. Der im Dezember 1379 verstorbene Geistliche Johann Murauer verf\u252 \'fcgte, dass er in St. Peter begraben und sein Verm\u246 \'f6gen den Benediktinern vermacht werde. Dagegen legte Anna IV. Widerspruch ein, da Murauer als Leibeigener (\plain \f1\i\lang1033\fs20 homo proprius\plain \f1\lang1033\fs20 ) des Stifts Nonnberg nur dort begraben werden k\u246 \'f6nne, und forderte das St. Peter vererbte Verm\u246 \'f6gen Murauers zur\u252 \'fcck. Erst nach sieben Monaten wurde der Prozess zugunsten St. Peters entschieden. \endash  Laut Chronicon novissimum werden die Prozessakten in einem \plain \f1\i\lang1033\fs20 instrumentum membraneum oblongum insolitae longitudinis\plain \f1\lang1033\fs20  \u252 \'fcberliefert. Ob die Originalakten noch existieren, bedarf noch eingehender Pr\u252 \'fcfung. Johannes Heller muss indessen Zugang zu der Originalfassung oder einer auf ihr basierenden \u220 \'dcberlieferung gehabt haben, aus der er die vorliegenden Ausz\u252 \'fcge mitteilte und Auslassungen mit \plain \f1\i\lang1033\fs20 etc.\plain \f1\lang1033\fs20  kennzeichnete. \endash  Zum Rechtsstreit vgl. Beda \plain \f1\scaps\lang1033\fs20 Seeauer\plain \f1\lang1033\fs20 , Novissimum Chronicon antiqui monasterii ad S. Petrum Salisburgi Ord. S. Benedicti. Augsburg 1772, S. 348; Placidus \plain \f1\scaps\lang1033\fs20 Berhandtsky\plain \f1\lang1033\fs20 , Auszug der Neuesten Chronick des alten Benediktiner Klosters zu St. Peter in Salzburg. Bd. 1. Salzburg 1782, S. 271f.; Franz \plain \f1\scaps\lang1033\fs20 Esterl\plain \f1\lang1033\fs20 , Chronik des adeligen Benediktiner-Frauen-Stiftes Nonnberg in Salzburg. Vom Entstehen desselben bis zum Jahre 1840 aus den Quellen bearbeitet. Salzburg 1841, Nr. 41 S. 49f.; Friedrich Karl \plain \f1\scaps\lang1033\fs20 Hermann\plain \f1\lang1033\fs20 , Das Begr\u228 \'e4bnisrecht der Abtei St. Peter, in: Festschrift St. Peter zu Salzburg 582-1982. St. Ottilien 1982 (SMGB 93), S. 79-128, hier S. 86f. \endash  Zum Grab des Johannes Murauer vgl. Die Grabdenkm\u228 \'e4ler von St. Peter und Nonnberg zu Salzburg von 1235 bis 1600. Bd. 1,4, bearb. von Michael \plain \f1\scaps\lang1033\fs20 Walz\plain \f1\lang1033\fs20  / Karl von \plain \f1\scaps\lang1033\fs20 Frey\plain \f1\lang1033\fs20 . Salzburg 1874, S. 458, 519. \endash  \plain \f1\lang1033\fs20\cf1 Zu Ortolf von Ovenstetten s. Hans \plain \f1\scaps\lang1033\fs20\cf1 Wagner\plain \f1\lang1033\fs20\cf1  / Herbert \plain \f1\scaps\lang1033\fs20\cf1 Klein\plain \f1\lang1033\fs20\cf1 , Salzburgs Domherren von 1300 bis 1514, in: Mitteilungen der Gesellschaft f\u252 \'fcr Salzburger Landeskunde 92 (1952), S. 1-81, hier S. 8, 46f. Nr. 75.}

