\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 S\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 Equitur materia consuetudinis, scilicet in octo\plain \f1\lang1033\fs24  (!, vielm. in quoto tempore)\plain \f1\i\lang1033\fs24  inducatur consuetudo et quociens sit necessarium \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 \u167 \'a7 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ex non scripto (Inst. 1.2.9). Visa casus posicione uisaque breui et compendiosa littere exposicione}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ut planius liqueat materia consuetudinis, sic credo distinguendum fuisse ut supra. Et sic est finis huius. Explicit tractatus siue materia consuetudinis\plain \f1\lang1033\fs24 .
