\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Foliierung, 19. Jh., mit Tinte in 50er-Abst\u228 \'e4nden, bei der Katalogisierung mit Bleistift erg\u228 \'e4nzt: 1-432. Wasserzeichen: \plain \f1\super\lang1033\fs20 1\plain \f1\lang1033\fs20 Schwert, Abb. s. {\field{\*\fldinst HYPERLINK "hida://6560[0].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 WZIS DE5580-Clm6602_13/16}}\plain \f1\lang1033\fs20 , identisch Clm 6601 Wz. 3; \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 Glocke, Abb. s. {\field{\*\fldinst HYPERLINK "hida://6560[1].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 WZIS DE5580-Clm6602_41/49}}\plain \f1\lang1033\fs20 , identisch Clm 6601 Wz. 4; \plain \f1\super\lang1033\fs20 3\plain \f1\lang1033\fs20 Ochsenkopf, Abb. s. {\field{\*\fldinst HYPERLINK "hida://6560[2].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 WZIS DE5580-Clm6602_65/67}}\plain \f1\lang1033\fs20 , identisch Clm 6601 Wz. 1; \plain \f1\super\lang1033\fs20 4\plain \f1\lang1033\fs20 Glocke 1, Abb. s. {\field{\*\fldinst HYPERLINK "hida://6560[3].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 WZIS DE5580-Clm6602_73}}\plain \f1\lang1033\fs20 , identisch Clm 6601 Wz. 5; \plain \f1\super\lang1033\fs20 5\plain \f1\lang1033\fs20 Ochsenkopf 1, Abb. s. {\field{\*\fldinst HYPERLINK "hida://6560[4].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 WZIS DE5580-Clm6602_114/120}}\plain \f1\lang1033\fs20 , identisch Clm 6601 Wz. 6; \plain \f1\super\lang1033\fs20 6\plain \f1\lang1033\fs20 Ochsenkopf 2, Abb. s. {\field{\*\fldinst HYPERLINK "hida://6560[5].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 WZIS DE5580-Clm6602_163/167/371}}\plain \f1\lang1033\fs20 , identisch Clm 6601 Wz. 7; \plain \f1\super\lang1033\fs20 7\plain \f1\lang1033\fs20 Ochsenkopf 3, Abb. s. {\field{\*\fldinst HYPERLINK "hida://6560[6].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 WZIS DE5580-Clm6602_259/265/386/432}}\plain \f1\lang1033\fs20 . \endash  Lagen: 11 VI\plain \f1\super\lang1033\fs20 132\plain \f1\lang1033\fs20  + VII\plain \f1\super\lang1033\fs20 146\plain \f1\lang1033\fs20  + (VII-1)\plain \f1\super\lang1033\fs20 159\plain \f1\lang1033\fs20  + 4 VI\plain \f1\super\lang1033\fs20 207\plain \f1\lang1033\fs20  + (VI-2+2)\plain \f1\super\lang1033\fs20 219\plain \f1\lang1033\fs20  + 7 VI\plain \f1\super\lang1033\fs20 303\plain \f1\lang1033\fs20  + 3 VII\plain \f1\super\lang1033\fs20 345\plain \f1\lang1033\fs20  + 7 VI\plain \f1\super\lang1033\fs20 429\plain \f1\lang1033\fs20  + II\plain \f1\super\lang1033\fs20 Spiegel\plain \f1\lang1033\fs20 ; Wortreklamanten. \endash  Schriftraum: 20-21 \u215 \'d7 13-13,5; 38-55 Zeilen. Geschrieben von vier H\u228 \'e4nden; {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Semihybrida Libraria-Currens}}\plain \f1\lang1033\fs20 : (Hand 1) 172\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 175\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -176\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Z. 9, 176\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Z. 25-231\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ; (Hand 3) 172\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 -175\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 176\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Z. 10-176\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Z. 24; {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hybrida Libraria-Currens}}\plain \f1\lang1033\fs20 : (Hand 4) 346\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -431\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ; (Hand 6) 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -171\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , 232\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -345\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ; die Z\u228 \'e4hlung der H\u228 \'e4nde richtet sich nach Clm 6601, dem ersten Band des Werks. \endash  Ausstattung im Wesentlichen wie {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 6601}}\plain \f1\lang1033\fs20 ; (134\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) Lombarde \u8250 \'9b\plain \f1\i\lang1033\fs20 S\plain \f1\lang1033\fs20 \u8249 \'8b, 7-zeilig, rot, mit Fadenausl\u228 \'e4ufern und ornamentaler Binnenverzierung. (402\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) Schema zu Lib. 4.4.14 \u252 \'fcber die Verwandtschaftsverh\u228 \'e4ltnisse. Digiti in Rot oder Braun (31\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 138\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , 142\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 , 182\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , 340\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ).}

