\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 231\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -235\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ps.-Jacobus de Arena}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De cessione actionum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Incipit tractatus cessionum compositus a do\plain \f1\lang1033\fs24 [mino] \plain \f1\i\lang1033\fs24 Jaco\plain \f1\lang1033\fs24 [bo] \plain \f1\i\lang1033\fs24 de Are\plain \f1\lang1033\fs24 [na] \plain \f1\i\lang1033\fs24 prout sequitur\plain \f1\lang1033\fs24 . \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Q\u8249 \'8bVoniam in corpore Juris sparsus et diffusus articulus de cessione iurium reperitur}}\plain \f1\i\lang1033\fs24  et a nemine collectus hucusque in vnum\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 respondeo quandocumque ante satisfaccionem eciam post sentenciam, ut ff. De tute\plain \f1\lang1033\fs24 [lae] \plain \f1\i\lang1033\fs24 et racio\plain \f1\lang1033\fs24 [nibus] \plain \f1\i\lang1033\fs24 distra\plain \f1\lang1033\fs24 [hendis], \plain \f1\i\lang1033\fs24 l. i \u167 \'a7 Non tantum\plain \f1\lang1033\fs24  (D. 27.3.1.18) \plain \f1\i\lang1033\fs24 et C. De contra\plain \f1\lang1033\fs24 [rio] \plain \f1\i\lang1033\fs24 Judi\plain \f1\lang1033\fs24 [cio], \plain \f1\i\lang1033\fs24 l. ii\plain \f1\lang1033\fs24  (C. 5.58.2) \plain \f1\i\lang1033\fs24 et ff. De fideiusso\plain \f1\lang1033\fs24 [ribus], \plain \f1\i\lang1033\fs24 l. Fideiussor \u167 \'a7 Idem\plain \f1\lang1033\fs24  (D. 46.1.16.3) \plain \f1\i\lang1033\fs24 respondit cum infinitis similibus. Explicit tractatus de cessione Iurium et accionum compositus per do\plain \f1\lang1033\fs24 [minum] \plain \f1\i\lang1033\fs24 Jaco\plain \f1\lang1033\fs24 [bum] \plain \f1\i\lang1033\fs24 de Arena\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\cbpat8\itap0 \plain \f1\lang1033\fs20\cf1 Druck: TUI 3,2, Sp. 74\plain \f1\super\lang1033\fs20\cf1 va\plain \f1\lang1033\fs20\cf1 -77\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1  \u167 \'a7 71. \endash  Lit.: \plain \f1\scaps\lang1033\fs20\cf1 Lange/Kriechbaum\plain \f1\lang1033\fs20\cf1  2, S. 444 Anm. 74; Bio-Bibliographical Guide, Report No. t069.}

