\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 265\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -266\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Bartolus de Saxoferrato (?)}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tractatus de copula et coniunctione. Tractatus de dictionibus}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Sequitur de copula et coniunccione\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (265\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -266\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Z. 9) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Q\u8249 \'8bvia tria operantur, repetunt et coniungunt}}\plain \f1\i\lang1033\fs24 . Adducunt ut l. Ea tamen ff. De le\plain \f1\lang1033\fs24 [gatis et fideicommissis] \plain \f1\i\lang1033\fs24 iii\u176 \'b0\plain \f1\lang1033\fs24  (\plain \f1\lang1033\fs22 D. 32.46) \plain \f1\i\lang1033\fs22 et l. \plain \f1\i\lang1033\fs24 Si stipulatus sis, ff. De vsuris\plain \f1\lang1033\fs24  [et fructibus] (D. 22.1.4) \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 tunc distingwunt vt l. Coniunccionem\plain \f1\lang1033\fs24 , [ff.] \plain \f1\i\lang1033\fs24 De ver\plain \f1\lang1033\fs24 [borum] \plain \f1\i\lang1033\fs24 signi\plain \f1\lang1033\fs24 [ficatione] (D. 50.16.29) \plain \f1\i\lang1033\fs24 et l. Que\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 vsu eo\plain \f1\lang1033\fs24 [dem] \plain \f1\i\lang1033\fs24 titulo\plain \f1\lang1033\fs24  (D. 50.16.158). \plain \f1\i\lang1033\fs24 Bar\plain \f1\lang1033\fs24 [tolus]. \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (266\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Z. 10-266\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 D}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8249 \'8b}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iccio vbi includit}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [positionem], }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 probatur C. De ac}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [tionibus] }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 et ob}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [ligationibus]}}\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 l. Accionem\plain \f1\lang1033\fs24  (wohl C. 2.4.4), \plain \f1\i\lang1033\fs24 dic ut ibi per Dy\plain \f1\lang1033\fs24 [num Mugellanum] \plain \f1\i\lang1033\fs24 in capitulo \u8218 \'82\plain \f1\lang1033\fs24 [Peccatum] \plain \f1\i\lang1033\fs24 non dimittiur\lquote , De re\plain \f1\lang1033\fs24 [gulis] \plain \f1\i\lang1033\fs24 iuris li. vi\u176 \'b0\plain \f1\lang1033\fs24  (VI 5.13.4; s. GW 8358 = BSB.-Ink D-142, Bl. [a 6]\plain \f1\super\lang1033\fs24 rab\plain \f1\lang1033\fs24 ) \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et solet notari in l. Illud, C. De sacro sanc\plain \f1\lang1033\fs24 [tis] [ecclesiis] (C. 1.2.19). \endash  Rest der Seite leer.
