\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -292\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Baldus de Ubaldis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Lectura super quarto et quinto libro Codicis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Codicis domini Justiniani sacratissimi principis liber quartus incipit. Baldus de Perusio\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 I\plain \f1\lang1033\fs24 [uris] \plain \f1\i\lang1033\fs24 V\plain \f1\lang1033\fs24 [triusque] \plain \f1\i\lang1033\fs24 Monarcha\plain \f1\lang1033\fs24 \u8249 \'8b Prolog: \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 M\u8249 \'8bos est et uelut quedam religio incipientis aliquid noui operis inuocare auxilium diuinitatis}}\plain \f1\i\lang1033\fs24  eiusque gratia cohoperante\plain \f1\lang1033\fs24  \u8230 \'85\endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit liber tertius. Incipit quartus liber. De rebus creditis et de iure iurando\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Rubrica\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Rubrica nostra diuiditur in duas partes siue intenciones. Nam primo ponitur intencio principis in generali\plain \f1\lang1033\fs24  \u8230 \'85\endash  (1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Causa\u8249 \'8b (C. 4.1.1). Causa iuramento decisa non retractatur pretextu periurii}}\plain \f1\i\lang1033\fs24 , nisi in casibus in lege expressis. H\plain \f1\lang1033\fs24 [oc] \plain \f1\i\lang1033\fs24 d\plain \f1\lang1033\fs24 [icit]. \plain \f1\i\lang1033\fs24 Et primo ponit regulam, secundo excepcionem, secunda ibi nisi\plain \f1\lang1033\fs24  \u8230 \'85; (2\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) C. 4.1.2-37.6\plain \f1\lang1033\fs22 ;\plain \f1\lang1033\fs24  (153\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs22 C. 4.37.\plain \f1\lang1033\fs24 7 mit Vermerk: \plain \f1\i\lang1033\fs24 Pone huius que est infra circa tale signum quod aliqua lectura\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 ponitur post l. Sanctimus\plain \f1\lang1033\fs24  [dar\u252 \'fcber Doppelkreuz mit drei Kreisen]; Druck: BSB-Ink U-27,2, Bl. m [5]\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ; (155\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs22 C. 4.\plain \f1\lang1033\fs24 38.1\plain \f1\lang1033\fs22 -\plain \f1\lang1033\fs24 14; (163\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs22 C. 4.38.\plain \f1\lang1033\fs24 15 mit Vermerk:\plain \f1\i\lang1033\fs24  Pro sequente ut infra circa tale signum\plain \f1\lang1033\fs24  [folgt Winkel mit drei Kreisen]; Druck: BSB-Ink U-27,2, Bl. nn ii\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  Z. 38-nn ii\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  Z. 17;\plain \f1\lang1033\fs22  \plain \f1\lang1033\fs24 (163\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs22 C. 4.\plain \f1\lang1033\fs24 39.1-51.\plain \f1\lang1033\fs22 5; (\plain \f1\lang1033\fs24 185\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs22 C. 4.51.6 mit \plain \f1\lang1033\fs24 Vermerk \plain \f1\lang1033\fs22 v\plain \f1\lang1033\fs24 on \plain \f1\expndtw15\scaps\lang1033\fs24 Korrektor 1\plain \f1\lang1033\fs24  in Lombarde \u8250 \'9b\plain \f1\i\lang1033\fs24 N\plain \f1\lang1033\fs22 \u8249 \'8b\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Hic non debet esse rubrica\plain \f1\lang1033\fs22 ; \plain \f1\lang1033\fs24 (186\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs22 C. 4.51.7 mit \plain \f1\lang1033\fs24 Vermerk von \plain \f1\expndtw15\scaps\lang1033\fs24 Korrektor \plain \f1\scaps\lang1033\fs24 1\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Hec l\plain \f1\lang1033\fs24 [ex] \plain \f1\i\lang1033\fs24 repetitur in fine lec\plain \f1\lang1033\fs24 [tur