\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 230\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -303\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Bartolus de Saxoferrato}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Lectura super tribus ultimis libris Codicis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa60\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit lectura excellentissimi legum doctoris domini Bartholi de Saxoferrato super tribus libris Codicis\plain \f1\lang1033\fs24 \u8249 \'8b [I]\plain \f1\i\lang1033\fs24 n nomine domini nostri Yhesu Christi eiusque matris Marie gloriose\plain \f1\lang1033\fs24  \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quia ubi Christus non est fundamentum, nullius boni operis superest beneficium}}\plain \f1\lang1033\fs24  (!, vielm. aedificium; C.1 q.1 c.26) \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 circa hoc principium venio ad Rubri\plain \f1\lang1033\fs24 [cam] \plain \f1\i\lang1033\fs24 De iure fisci Codicis domini Justiniani principis\plain \f1\lang1033\fs24 . \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit liber nonus. Hic incipit decimus. De iure fisci Rubrica\plain \f1\lang1033\fs24 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24 G\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 losa continuat duobus modis. Primo de occasione criminum\plain \f1\lang1033\fs24  \u8230 \'85; (231\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 S\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24 i prius\plain \f1\lang1033\fs24  (C. 10.1.1). \plain \f1\i\lang1033\fs24 Hec lex est notabilis et bona et male intelligitur communiter et h\plain \f1\lang1033\fs24 [oc] \plain \f1\i\lang1033\fs24 d\plain \f1\lang1033\fs24 [icit]: \plain \f1\i\lang1033\fs24 In dubio donatarius a fisco conuentus ypothecaria, debet probare donacionem precessisse\plain \f1\lang1033\fs24  \u8230 \'85; (231\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) C. 10.1.2-\plain \f1\lang1033\fs22 30.3\plain \f1\lang1033\fs24 ; 32.1-55.3; 57.1\plain \f1\lang1033\fs22 -\plain \f1\lang1033\fs24 78.1; \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit liber decimus. Incipit liber undecimus. De lucrifera\plain \f1\lang1033\fs24  (?, vielm. lustralis) \plain \f1\i\lang1033\fs24 auri colla\plain \f1\lang1033\fs24 [tione]. \plain \f1\i\lang1033\fs24 Constitucio greca\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 De nauiculariis siue naucreliis\plain \f1\lang1033\fs24  (!, vielm. naucleris) \plain \f1\i\lang1033\fs24 publicis non transporcionibus\plain \f1\lang1033\fs24  (!, vielm. transportantibus) \plain \f1\i\lang1033\fs24 Rubrica\plain \f1\lang1033\fs24 \u8249 \'8b.\plain \f1\lang1033\fs22  \endash  \plain \f1\lang1033\fs24 (260\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) C. 11.2.1-15.1\plain \f1\lang1033\fs22 ; \plain \f1\lang1033\fs24 17.1-20.1; 22.1\plain \f1\lang1033\fs22 -\plain \f1\lang1033\fs24 43.11\plain \f1\lang1033\fs22 ; \plain \f1\lang1033\fs24 45.1; 48.1\plain \f1\lang1033\fs22 -\plain \f1\lang1033\fs24 53.1; 59.1-64.\plain \f1\lang1033\fs22 3\plain \f1\lang1033\fs24 ; 69.1-76.1;\plain \f1\lang1033\fs22  \plain \f1\lang1033\fs24 78.1-2. \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit liber xi\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24 . Incipit liber xii\plain \f1\i\super\lang1033\fs24 us\plain \f1\i\lang1033\fs24 . De dignitatibus Rubrica\plain \f1\lang1033\fs24 \u8249 \'8b.\plain \f1\lang1033\fs22  \endash  \plain \f1\lang1033\fs24 (283\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) C. 12.1.1-18; 3.1\plain \f1\lang1033\fs22 -5\plain \f1\lang1033\fs24 .4; 7.1\plain \f1\lang1033\fs22 -\plain \f1\lang1033\fs24 26.2; 28.1-30.1; 33.1-7; 35.1-40.11; 42.1\plain \f1\lang1033\fs22 -\plain \f1\lang1033\fs24 46.\plain \f1\lang1033\fs22 4\plain \f1\lang1033\fs24 ; 49.1-\plain \f1\lang1033\fs22 5\plain \f1\lang1033\fs24 5.1; 57.1-\plain \f1\lang1033\fs22 1\plain \f1\lang1033\fs24 4; 59.1-62.4; tit. 63.1, expl.: \u8230 \'85 \plain \f1\i\lang1033\fs24 et eciam officiales, qui maleficia dissimulacione non puniunt, nam sunt acriter puniendi, ut hic et supra De deserto\plain \f1\lang1033\fs24 [ribus], \plain \f1\i\lang1033\fs24 l. i\plain \f1\lang1033\fs24  (C. 12.45.1). \plain \f1\i\lang1033\fs24 Bart\plain \f1\lang1033\fs24 [olus] \plain \f1\i\lang1033\fs24 le\plain \f1\lang1033\fs24 [gum] \plain \f1\i\lang1033\fs24 doc\plain \f1\lang1033\fs24 [tor]. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Et sic est finis horum terni librorum Codicis domini Bartoli de Saxoferrato\plain \f1\lang1033\fs24 \u8249 \'8b. \endash  303\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -304\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 C. 10.1.1-12.63.1. \endash  In lib. 12 fehlen die Rubriken au\u223 \'dfer f\u252 \'fcr tit. 38, 40, 42, 44-45 und 49. \endash  Druck: VD16 B 576, Bd. 8, S. 1-147. \endash  Lit.: \plain \f1\scaps\lang1033\fs20 Casamassima\plain \f1\lang1033\fs20 , Iter Germanicum, Nr. 114,II, S. 138; Francesco \plain \f1\scaps\lang1033\fs20 Calasso\plain \f1\lang1033\fs20 , in: DBI 6 (1964), S. 640-669, hier S. 648 (Hs. genannt); CALMA 2 Nr. 5, S. 103; \plain \f1\scaps\lang1033\fs20 Lange/Kriechbaum\plain \f1\lang1033\fs20  2, S. 723f.
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 \par}

