\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (241\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tiberiades est regio iuxta flumen Tiberis constituta, est autem Tyberis flumen notabile}}\plain \f1\i\lang1033\fs24  in Italie partibus\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 voluas ergo circulariter et habebis grossitiem vegetis. Explicit tractatus de alluuione. Incipit tractatus de insula\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (247\plain \f1\super\lang1033\fs24 ra\plain \f1\i\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Insula, que in mari nascitur, quod raro accidit, occupantis fit}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Hec uerba sunt ff. De acquirendo rerum dominio, l. Adeo \u167 \'a7 Insula \plain \f1\lang1033\fs24 (D. 41.1.7 \u167 \'a7 3-4) \u8230 \'85 \plain \f1\i\lang1033\fs24 Ait ergo: Insula est locus circumdatus aquis\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et\plain \f1\lang1033\fs24  [per] \plain \f1\i\lang1033\fs24 predicta multas possunt dirimere questiones\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (252\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Superest, vt de alueo dicamus, sequentes ordinem, quem Jurisconsultus secutus est}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 solum eodem modo et ita dicit glosa super hac lege. Explicit tercius liber. Deo gracias matrique eius gloriose\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
