\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 146\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -150\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Bartolus de Saxoferrato}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tractatus super constitutione Qui sint rebelles}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (Rubrik) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 H\u8249 \'8bEc rubrica etiam est magistraliter posita. Et supra dixi de modo procedendi, ut imponatur pena}}\plain \f1\i\lang1033\fs24  per sentenciam\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (Gesetz in doppelter Schriftgr\u246 \'f6\u223 \'dfe) \plain \f1\i\lang1033\fs24 Idem ad perpetuam rei memoriam. Quoniam nuper est ad auditum nostrum deductum\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 nostre camere soluendarum se nouerit incursum. Datum Pisis\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (Kommentar) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quoniam nuper\u8249 \'8b Primo ponit dubium, secundo raciones, que mouent principem ad decisionem}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et istud datum est commune ad hanc constitutionem et precedentem. Laus deo matrique eius gloriose\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kolophon}}\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Explicit apparatus eximii Iuris interpretis d\plain \f1\lang1033\fs24 [omini] \plain \f1\i\lang1033\fs24 Bar\plain \f1\lang1033\fs24 [toli] \plain \f1\i\lang1033\fs24 de Saxoferrato super duabus extrauagantibus latis per d\plain \f1\lang1033\fs24 [ominum] \plain \f1\i\lang1033\fs24 Henricum romanorum Imperatorem\plain \f1\lang1033\fs24 . \endash  Rest der Spalte leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Druck des Gesetzes vom 2. April 1313: MGH Leges 2, S. 545; Druck des Traktats einschlie\u223 \'dflich Gesetz: VD16 B 576, Bd. [10], S. 285-291. \endash  Lit.: \plain \f1\scaps\lang1033\fs20 Casamassima\plain \f1\lang1033\fs20 , Iter Germanicum, Nr. 118,III, S. 142 (Hs. genannt); CALMA 2, Nr. 161 S. 156; \plain \f1\scaps\lang1033\fs20 Lange/Kriechbaum\plain \f1\lang1033\fs20  2, S. 728.}

