\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Das {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kolophon}}\plain \f1\lang1033\fs20  nennt auf 287\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Angelus de Castro}}\plain \f1\lang1033\fs20  sowie das Datum 9. April 1446; offensichtlich nimmt der Schreiber Bezug auf Castros Lehrt\u228 \'e4tigkeit im Studienjahr 1445/1446, in dem dieser mit der Abendvorlesung zum kanonischen Recht betraut war (s. \plain \f1\scaps\lang1033\fs20 Belloni\plain \f1\lang1033\fs20 , Professori giuristi, Falttafel VI.1 nach S. 88). \endash  Vorliegende Hs. stammt aus der sog. \plain \f1\expndtw15\scaps\lang1033\fs20 Padua-Gruppe\plain \f1\lang1033\fs20  (s. Einleitung, Kap. I.1.3.2).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

