\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 182\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -199\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Bartolus de Saxoferato}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 in Repetitio in D. 1.1.9 der \u220 \'dcberarbeitung von Laurus de Palazzolis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Im Kopfsteg: \plain \f1\i\lang1033\fs24 Repetitio l. Omnes populi De iusti\plain \f1\lang1033\fs24 [tia] \plain \f1\i\lang1033\fs24 et iure ff\plain \f1\lang1033\fs24 . \endash  \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O\u8249 \'8bmnes populi \u8230 \'85 (D. 1.1.9). Omni populo iurisdiccionem habenti permittitur sibi ius proprium constituere}}\plain \f1\i\lang1033\fs24 , quod ius ciuile vocatur\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 dic ut supra, magna tamen opinio Bar\plain \f1\lang1033\fs24 [toli] \plain \f1\i\lang1033\fs24 est. Laus deo. Amen\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Hec lex fuit publice lecta et commentata per eximium vtriusque iuris doctorem, d\plain \f1\lang1033\fs24 [ominum] \plain \f1\i\lang1033\fs24 Laurum de Palazoliis in nostro studio Paduano, ipso legente extraordinaria\plain \f1\lang1033\fs24 [m]\plain \f1\i\lang1033\fs24  ord\plain \f1\lang1033\fs24 [inarie] \plain \f1\i\lang1033\fs24 et ipso legente prima\plain \f1\lang1033\fs24 [m] \plain \f1\i\lang1033\fs24 parte\plain \f1\lang1033\fs24 [m]\plain \f1\i\lang1033\fs24  ff. veteris. {\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Et completa fuit die ultima Decembris xliiii\u176 \'b0. \u8250 \'9bIntilbres}}\plain \f1\lang1033\fs24 \u8249 \'8b \endash  Rest der Seite leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
