\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Im Kopfsteg: \plain \f1\i\lang1033\fs24 Repeticio l. Imperium ff. De iur\plain \f1\lang1033\fs24 [isdictione] \plain \f1\i\lang1033\fs24 o\plain \f1\lang1033\fs24 [mnium] \plain \f1\i\lang1033\fs24 iudi\plain \f1\lang1033\fs24 [cium]. \endash  \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 I\u8249 \'8bmperium ff. De iurisdiccione omnium iudicum Repeticio. Ordo presentis legis erit iste, nam, cum ex communi sentencia habeamus}}\plain \f1\i\lang1033\fs24 , quod aliud est iurisdictio in genere et aliud imperium et istud imperium subdiuiditur in merum et mixtum\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ut est tex\plain \f1\lang1033\fs24 [tus] \plain \f1\i\lang1033\fs24 in l. fi\plain \f1\lang1033\fs24 [nale] \plain \f1\i\lang1033\fs24 C. De pedan\plain \f1\lang1033\fs24 [eis] \plain \f1\i\lang1033\fs24 iudi\plain \f1\lang1033\fs24 [cibus] (C. 3.3.5), \plain \f1\i\lang1033\fs24 que potest intellegi in minoribus causis et minimis\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Et per hec est expedita lex ista cum omni sua materia etc. per d[ominum] Franciscum de Capitibusliste, tunc ordinarium iuris ciuilis Padue Anno etc xliiii\u176 \'b0.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
