\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 292\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -293\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Consilia super quarta canonica}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (292\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Johannes de Monte Murlo}}\plain \f1\scaps\lang1033\fs24 : \plain \f1\i\lang1033\fs24 In nomine domini super quarta canonica, quam pretendunt habere episcopi in dyocesibus suis. Consilium domini Jo\plain \f1\lang1033\fs24 [hannis] \plain \f1\i\lang1033\fs24 de Monte Murlo decretorum doctoris\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Questio talis est. Contingit multociens, quod quidam laici ciuitatis in mortis articulo}}\plain \f1\i\lang1033\fs24  constituti condunt sua testamenta\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ut in c. Cum tibi Extra De testa\plain \f1\lang1033\fs24 [mentis] (X 3.26.13). \plain \f1\i\lang1033\fs24 Et ita intelligo iura allegata vltimo pro 2\plain \f1\i\super\lang1033\fs24 a\plain \f1\i\lang1033\fs24  parte et ita iura satis inducuntur ad consonanciam et concordiam. Consilium Jo\plain \f1\lang1033\fs24 [hannis de Monte Murlo]. \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (292\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -293\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Johannes Andreae}}\plain \f1\scaps\lang1033\fs24 :\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Consilium postea super predictis d\plain \f1\lang1033\fs24 [omini] \plain \f1\i\lang1033\fs24 Jo\plain \f1\lang1033\fs24 [hannis] \plain \f1\i\lang1033\fs24 An\plain \f1\lang1033\fs24 [reae] \plain \f1\i\lang1033\fs24 in titulis sequentibus\plain \f1\lang1033\fs24 . \endash  \plain \f1\lang1033\fs24\chcbpat17  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Testator pro incertis male ablatis reliquid (!) libros xx in disposicionem commissarii sui}}\plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 nisi quarta decimarum operis. Et dictum prescriptum esse contra eos, qui alias quartas non habeant. Et ita consulo ego Jo\plain \f1\lang1033\fs24 [hannes] \plain \f1\i\lang1033\fs24 An\plain \f1\lang1033\fs24 [dreae] \plain \f1\i\lang1033\fs24 decre\plain \f1\lang1033\fs24 [torum] \plain \f1\i\lang1033\fs24 doctor\plain \f1\lang1033\fs24 .\plain \f1\lang1033\fs20  \endash  \plain \f1\lang1033\fs24 293\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -294\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
