 14; (Hand 5) 76\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1 -93\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 , 130\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1  Z. 15-147\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 , 220\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1 -245\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 ; (Hand 6) 94\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1 -111\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 ; (Hand 7) 148\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1 -165\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 , 202\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1 -219\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 ; {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17\cf1 Semihybrida Currens-Libraria}}\plain \f1\lang1033\fs20\cf1 : (Hand 3) 45\plain \f1\super\lang1033\fs20\cf1 va\plain \f1\lang1033\fs20\cf1 -57\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 ; {\field{\*\fldinst HYPERLINK "hida://5704[2]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17\cf1 Hybrida Libraria}}\plain \f1\lang1033\fs20\cf1 : (Hand 4) 58\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1 -75\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 , 166\plain \f1\super\lang1033\fs20\cf1 ra\plain \f1\lang1033\fs20\cf1 -183\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 , 189\plain \f1\super\lang1033\fs20\cf1 rb\plain \f1\lang1033\fs20\cf1 -201\plain \f1\super\lang1033\fs20\cf1 vb\plain \f1\lang1033\fs20\cf1 ; H\u228 \'e4ndewechsel stimmen in der Regel mit den Lagengrenzen \u252 \'fcberein. Lombarden, 1-3-zeilig, mit Punktverdickungen und Fadenausl\u228 \'e4ufern, bei Hand 5 teils auch in Herzbl\u228 \'e4ttern endend (u.a. 144\plain \f1\supe