\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 174\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -177\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sophismata}}
\par \pard\fi0\li0\tx1380\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\tx1380\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Sophismata poetarum pro \plain \f1\lang1033\fs24 [doctrinali] \plain \f1\i\lang1033\fs24 Alexandri et super secunda parte\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (174\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Di faciunt sine me ne moriatur ego \plain \f1\lang1033\fs24 (\plain \f1\scaps\lang1033\fs24 Rosier\plain \f1\lang1033\fs24  Nr. 33). \plain \f1\i\lang1033\fs24 Pro isto sophismate est notandum, quod oracio debet esse congrua dupliciter ... \plain \f1\lang1033\fs24 \endash  Weitere Sophismata (Nrn. nach \plain \f1\scaps\lang1033\fs24 Rosier\plain \f1\lang1033\fs24 ): \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 Nr. 47; (174\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 3{\field{\*\fldinst HYPERLINK "hida://5650[23].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Priscianus scribe}}\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 Nr. 122; (174\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 5{\field{\*\fldinst HYPERLINK "hida://5650[26].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tu mecum iuste debemus iura tenere}}\plain \f1\lang1033\fs24 ;\plain \f1\lang1033\fs22  \plain \f1\super\lang1033\fs24 6\plain \f1\lang1033\fs24 Nr. 91;\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (174\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 7\plain \f1\lang1033\fs24 Nr. 5; (175\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 8{\field{\*\fldinst HYPERLINK "hida://5650[27].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tu, quid ego et populus desiderat}}\plain \f1\i\lang1033\fs24 , audi\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 9\plain \f1\lang1033\fs24 Nr. 73-74; \plain \f1\super\lang1033\fs24 10\plain \f1\lang1033\fs24 Nr. 37; (175\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 11{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cappa Socratis}}\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 12\plain \f1\lang1033\fs24 Nr. 120; (175\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 13\plain \f1\lang1033\fs24 Nr. 185; \plain \f1\super\lang1033\fs24 14\plain \f1\lang1033\fs24 Nr. 119; (175\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 )\plain \f1\lang1033\fs22  \plain \f1\super\lang1033\fs24 15{\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Homo nudos pedes corisat}}\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 16\plain \f1\lang1033\fs24 Nr. 156; (176\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 17\plain \f1\lang1033\fs24 Nr. 177; \plain \f1\super\lang1033\fs24 18\plain \f1\lang1033\fs24 Nr. 81; \plain \f1\super\lang1033\fs24 19\plain \f1\lang1033\fs24 Nr. 6; (176\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 )\plain \f1\lang1033\fs22  \plain \f1\super\lang1033\fs24 20{\field{\*\fldinst HYPERLINK "hida://5650[24].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Socrates est abilis pugnare}}\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 21\plain \f1\lang1033\fs24 Nr. 153; \plain \f1\super\lang1033\fs24 22{\field{\*\fldinst HYPERLINK "hida://5650[25].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Socrates est animalia}}\plain \f1\lang1033\fs24  (!, vielm. animal); (176\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 )\plain \f1\lang1033\fs22  \plain \f1\super\lang1033\fs24 23\plain \f1\lang1033\fs24 Nr. 111;\plain \f1\lang1033\fs22  \plain \f1\super\lang1033\fs24 24\plain \f1\lang1033\fs24 Nr. 186; (176\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 25\plain \f1\lang1033\fs24 Nr. 173; \plain \f1\super\lang1033\fs24 26\plain \f1\lang1033\fs24 Nr. 171; (177\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 27\plain \f1\lang1033\fs24 Nr. 182-183; (177\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 28\plain \f1\lang1033\fs24 Nr. 80. \u8250 \'9b\plain \f1\i\lang1033\fs24 Expliciunt sophismata bona\plain \f1\lang1033\fs24 \u8249 \'8b.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Syntaktisch-semantische Erkl\u228 \'e4rungen grammatikalischer Regeln und Ausnahmen anhand von 28 Beispiels\u228 \'e4tzen (Sophismata) f\u252 \'fcr den Schulunterricht. Quellen der Sophismata sind antike und mittelalterliche Autoren und Grammatiker sowie die Bibel und Merks\u228 \'e4tze aus der Sprachlogik. Die Nummern werden zitiert nach Ir\u232 \'e8ne \plain \f1\scaps\lang1033\fs20 Rosier\plain \f1\lang1033\fs20 , Les sophismes grammaticaux au Xlll\plain \f1\super\lang1033\fs20 e\plain \f1\lang1033\fs20  si\u232 \'e8cle, in: Medioevo 17 (1991), S. 175-230, hier S. 219-230; dort auch Nachweis der Quellen, aus denen die Sophismata entnommen wurden. Bei Rosier nicht nachweisbare Sophismata werden in vollem Wortlaut aufgef\u252 \'fchrt. \endash  Parallel\u252 \'fcberlieferung: Bremen, SuUB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 msb 0007}}\plain \f1\lang1033\fs20 , 183\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 . \endash  Lit.: La Sophistria de Robertus Anglicus. \u201 \'c9tude et \u233 \'e9dition critique par Anne \plain \f1\scaps\lang1033\fs20 Grondeux\plain \f1\lang1033\fs20  et Ir\u232 \'e8ne \plain \f1\scaps\lang1033\fs20 Rosier\plain \f1\lang1033\fs20 -\plain \f1\scaps\lang1033\fs20 Catach\plain \f1\lang1033\fs20 . Paris 2006 (Sic et non).}

