\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 {\field{\*\fldinst HYPERLINK "hida://5240[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Holzdeckelband}}\plain \f1\lang1033\fs20  mit hellem {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Lederbezug}}\plain \f1\lang1033\fs20  aus der Ingolst\u228 \'e4dter {\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4600/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Werkstatt T.S.}}\plain \f1\lang1033\fs20  ({\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4998/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 EBDB w004253}}\plain \f1\lang1033\fs20 ) mit \plain \f1\lang1033\fs20\chcbpat17  {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Rollen}}\plain \f1\lang1033\fs20  ({\field{\*\fldinst HYPERLINK "hida://6560[1].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 r003139}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://6560[2].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 r003140}}\plain \f1\lang1033\fs20 ), {\field{\*\fldinst HYPERLINK "hida://5300[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Platte}}\plain \f1\lang1033\fs20  ({\field{\*\fldinst HYPERLINK "hida://6560[3].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 p002644}}\plain \f1\lang1033\fs20 ) und {\field{\*\fldinst HYPERLINK "hida://5300[2]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Einzelstempel}}\plain \f1\lang1033\fs20  ({\field{\*\fldinst HYPERLINK "hida://6560[4].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 s032492}}\plain \f1\lang1033\fs20 ); auf dem Vorderdeckel eingepr\u228 \'e4gt die Initialen \plain \f1\i\lang1033\fs20 I\plain \f1\lang1033\fs20 [hannes] \plain \f1\i\lang1033\fs20 R\plain \f1\lang1033\fs20 [eisacher]\plain \f1\i\lang1033\fs20  L\plain \f1\lang1033\fs20 [andshut] \plain \f1\i\lang1033\fs20 B\plain \f1\lang1033\fs20 [oius] und Jahreszahl \plain \f1\i\lang1033\fs20 1618\plain \f1\lang1033\fs20 ; zwei Schlie\u223 \'dfb\u228 \'e4nder; Blattweiser. Auf dem vorderen Spiegel {\field{\*\fldinst HYPERLINK "hida://6560[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Exlibris}}\plain \f1\lang1033\fs20  von 1696 des {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johann Franz Eckher von Kapfing und Liechteneck}}\plain \f1\lang1033\fs20 , Bf. von Freising ({\field{\*\fldinst HYPERLINK "hida://6560[0].6770/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Warnecke Nr. 557}}\plain \f1\lang1033\fs20 ), vgl. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 6754}}\plain \f1\lang1033\fs20 . }

