\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johannes Crotus de Monteferrato}}\plain \f1\lang1033\fs20  (\u8224 \'86 1540) war als Rechtslehrer in Bologna und Pisa t\u228 \'e4tig. Die Aufzeichnungen hat Sigismund Scheufler wohl w\u228 \'e4hrend eines Studienaufenthalts in Bologna angefertigt; nachgewiesen ist er als Student in Bologna zwischen 1497 und 1503 (\plain \f1\scaps\lang1033\fs20 Schottenloher\plain \f1\lang1033\fs20 , S. 377f.). Zu Scheufler s. die Einleitung, Kap. I.1.5.2 sowie {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 6613}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 6722}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 6743}}\plain \f1\lang1033\fs20  (von seiner Hand), {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 6715}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 6741}}\plain \f1\lang1033\fs20  (aus seinem Besitz).}

