\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -178\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    \plain \f1\b\lang1033\fs24 Monaldus de Iustinopoli\plain \f1\lang1033\fs24  \plain \f1\b\lang1033\fs24 OFM: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Summa de iure canonico (Summa Monaldina)}}
