\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24\cf1 Theologice veritatis doctori optimo, d\plain \f1\lang1033\fs24\cf1 [omino] \plain \f1\i\lang1033\fs24\cf1 Johanni Wenck arcium restauratorum\plain \f1\lang1033\fs24\cf1  (!) \plain \f1\i\lang1033\fs24\cf1 ac firmo domicilio, patri suo colend\plain \f1\lang1033\fs24\cf1 [issim]\plain \f1\i\lang1033\fs24\cf1 o. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Quamquam iam dudum, doctor famosissime, fama iugens in Italia}}\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 vale et me, ut facis, ama. Datum x kalendis septembris 1456\plain \f1\lang1033\fs24  (23. August 1456). \plain \f1\i\lang1033\fs24 Finit illa epistola pulchra\plain \f1\lang1033\fs24 .
