\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Epistola perfidi Theucri\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 missa domino pape Pio secundo. Daglosius Soldanus, affinis deorum, Babilonie imperator\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Pio secundo magno romanorum sacerdoti \plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 datum in Acharon\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 ciuitate nostra opulentissima sub Nilum Egipti sita. Anno natiuitatis nostre vicesimo nono deorum nostrorum Machumete, Algoriste regno autem nostro primo 1459. Finit illa epistola\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 
