\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Exultat animus quocumque scribendi ad te argumento oblato}}\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 vale et si hec tibi res cordi sit, me tibi carum cognoscam. Si iterum vale et mutuo fac amer. Finis\plain \f1\lang1033\fs24\cf1 .}

