\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Missus iunior a patris edibus die xii mensis Iulii pro libris quibusdam}}\plain \f1\i\lang1033\fs24\cf1  ad tra\plain \f1\lang1033\fs24\cf1 [n]\plain \f1\i\lang1033\fs24\cf1 sscribendum, accomodandum a fratribus epistolam petitoriam ab illustrissimo principe nostro ad eos proferebam\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 quando ex polluto corde sordida illa verba profluxerant, sed calamum ne hac de re lacius perscribam, reprimo. Finis.}

