\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Alcuinus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Dialogus de rhetorica}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22 
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 Titel am oberen Rand (wohl von Aventinus nachgetragen): \plain \f1\i\lang1033\fs24 Albini Karoli magistri\plain \f1\lang1033\fs22  (\plain \f1\lang1033\fs24 ?, Tinte zerlaufen\plain \f1\lang1033\fs22 )\plain \f1\i\lang1033\fs24  preceptoris Historica et\plain \f1\lang1033\fs22  (?)\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 philosophia\plain \f1\lang1033\fs24 . Einleitungsverse: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Qui rogo ciuiles cupiat cognoscere mores}}\plain \f1\lang1033\fs24  / ... \plain \f1\i\lang1033\fs24 mel tibi portat apes\plain \f1\lang1033\fs24  (4 Dist\plain \f1\lang1033\fs22 ichen\plain \f1\lang1033\fs24 ). \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Disputatio de rethorica et de uirtu\u8249 \'8b/tibus sapientissimi regis Karli et / \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Albini magistri. karlus \plain \f1\lang1033\fs22 (\plain \f1\lang1033\fs24 !\plain \f1\lang1033\fs22 )\plain \f1\i\lang1033\fs24  rex et Albinus magister\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 K: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quia te uenerande magister Albine deus adduxit et reduxit}}\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs22 ...\endash ...\plain \f1\lang1033\fs24  (23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 legentem non corrumpit\plain \f1\lang1033\fs24 . \endash  (23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Schematische \plain \f1\lang1033\fs22 Fede\plain \f1\lang1033\fs24 rzeichnungen mit Erkl\u228 \'e4rungen: (25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Porro. Sapientia\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs22 (\plain \f1\lang1033\fs24 !\plain \f1\lang1033\fs22 )\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 veteres philosophiam vocaverunt\plain \f1\lang1033\fs24  ...\plain \f1\lang1033\fs22 \endash \plain \f1\lang1033\fs24  (26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) ...  \plain \f1\i\lang1033\fs24 modum inponit\plain \f1\lang1033\fs24 . (26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O uos est aetas iuuenes}}\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs22 ...\endash ...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 ut nomen in orbe tuum\plain \f1\lang1033\fs22  (7 Distichen).
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 
