\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -136\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Benedictiones, praefationes, orationes}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio cymiterii. Primitus canantur\plain \f1\lang1033\fs24  ...\u8249 \'8b PRG LIV. \endash  (112\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio omnivm ornamentorum ad cvltvm Dei et aecclesiae pertinentivm. Benedictio linteaminvm\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 74-75. \endash  (113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio ad omnia uasa et instrumenta\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 77. \endash  (113\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio ad omnia ornamenta in usum aecclesiae uel altaris\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 78. \endash  (114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Item benedictio uestimentorum sacerdotalium siue leuiticorum atque sequentis ordinis mi\plain \f1\lang1033\fs24 \u8249 \'8b[nistrantium] PRG XL, 79. \endash  (114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio ad albas, planetas, stolas et singula benedicenda\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 80. \endash  (115\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio ad stolas vel planetas quando leuite uel presbyteri ordinandi sunt\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 81-82. \endash  (116\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio corporalis\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 83-85. \endash  (116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Praefatio eucharistalis id est vasculi in quo eucharistia reconditur\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 86-87. \endash  (117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Praefatio ad patinam\plain \f1\lang1033\fs24  (!)\plain \f1\i\lang1033\fs24  consecrandam\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 89, 91, 87. \endash  (117\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Praefatio calicis\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 92, 93, 95. \endash  (118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio tvribvli\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 106-107. \endash  (118\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio incensi uel thimiamatis\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 108-110. \endash  (119\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio crvcis\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 97-104. \endash  (122\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio crucis metallizatae\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 105. \endash  (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Praefatio ad consecrandas capsas\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 111-115. \endash  (126\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Prefatio ciborii id est umbraculi altaris\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 116-117. \endash  (127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Item consecratio minoris id est itinerarii ciborii\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 118. \endash  (127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Praefatio tabule itinerariae\plain \f1\lang1033\fs24 \u8249 \'8b PRG XL, 120-122. \endash  (128\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio in dedicatione baptisterii\plain \f1\lang1033\fs24 \u8249 \'8b PRG LII. \endash  (128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Benedictio super munus quod quis ecclesiae offert honori\plain \f1\lang1033\fs24 \u8249 \'8b PRG XLVIII. \endash  (129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ordo ad benedicendum aecclesiae signum\plain \f1\lang1033\fs24 \u8249 \'8b PRG LI. \endash  (133\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Reconciliatio uiolate aecclesiae\plain \f1\lang1033\fs24 \u8249 \'8b PRG L. \endash  (136\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) leer.}

