\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -198\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Franciscus de Capitibusliste}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Repetitio in D. 4.8.1-19}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Im Kopfsteg oben rechts: \plain \f1\i\lang1033\fs24 Rubrica de arbitris. Item ti\plain \f1\lang1033\fs24 [tulus] d\plain \f1\i\lang1033\fs24 e arbitris lectus est per d\plain \f1\lang1033\fs24 [ominum] \plain \f1\i\lang1033\fs24 Franciscum Capitibusliste ordinarium iuris ciuilis Padue\plain \f1\lang1033\fs24 . \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 Rubrica de Arbitris seu de receptis, qui in se recipiunt arbitrium, vt sentenciam dicant\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 In nomine sancte et indiuidue trinitatis \plain \f1\lang1033\fs24 \u8230 \'85\plain \f1\i\lang1033\fs24  Amen\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sequitur ti[tulus] De arbitris, quam intendo quantum est in me solempniter communicare}}\plain \f1\i\lang1033\fs24  et in eo ponere super locis contingentibus omnes questiones in materia arbitrorum et arbitramentorum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  (167\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Compromissum (D. 4.8.1). Lex ista breuis est et non potest breuius summari}}\plain \f1\i\lang1033\fs24  et tractabitur super ea noua materia\plain \f1\lang1033\fs24  \u8230 \'85; (172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) D. 4.8.2-3, 5, 7, 9, 11, 13, 15-17, 19, (198\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) expl.: \u8230 \'85\plain \f1\i\lang1033\fs24  et in c. Quod\plain \f1\lang1033\fs24  [ad] \plain \f1\i\lang1033\fs24 consultacionem, De\plain \f1\lang1033\fs24  [sententia et] \plain \f1\i\lang1033\fs24 re iudi\plain \f1\lang1033\fs24 [cata] (X 2.27.15), \plain \f1\i\lang1033\fs24 non iusto tantum, sed sum contentus remissionis\plain \f1\lang1033\fs24 || wohl Textabbruch. \endash  Rest der Seite sowie 198a\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 D. 4.8.1-19. \endash  Lit.: \plain \f1\scaps\lang1033\fs20 Belloni\plain \f1\lang1033\fs20 , Professori giuristi, S. 196 (Hs. genannt); CALMA 3 Nr. 14, S. 409.}

