\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Lamperti episcopi et martiris \plain \f1\lang1033\fs24 (17.9.) L[ectio] e\plain \f1\i\lang1033\fs24 x omelia beati Greogorii pape \u8218 \'82Si quis uult post me venire\plain \f2\lang1033\fs22 \lquote \plain \f1\i\lang1033\fs24 . Ew\plain \f1\lang1033\fs24 [angeliu]\plain \f1\i\lang1033\fs24 m: Nisi granum\plain \f1\lang1033\fs24  (Io 12,24). \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2213, 2299, 2301.\endash  \plain \f1\super\lang1033\fs24 2\plain \f1\i\lang1033\fs24 Mavricii cum sociis suis\plain \f1\lang1033\fs24  (22.9.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2099. \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\i\lang1033\fs24 Jeronimi presbiteri\plain \f1\lang1033\fs24  (30.9.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2126, 2365, 2395f. \endash  \plain \f1\super\lang1033\fs24 4\plain \f1\i\lang1033\fs24 Remigii episcopi\plain \f1\lang1033\fs24  (1.10.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2128, 2378. \endash  \plain \f1\super\lang1033\fs24 5\plain \f1\i\lang1033\fs24 Dionisii sociorumque eius\plain \f1\lang1033\fs24  (9.10.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2337. \endash  \plain \f1\super\lang1033\fs24 6\plain \f1\i\lang1033\fs24 Undecim milium virginum\plain \f1\lang1033\fs24  (21.10.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2430, 2434. \endash  \plain \f1\super\lang1033\fs24 7\plain \f1\i\lang1033\fs24 Symonis et Iude\plain \f1\lang1033\fs24  (28.10.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2277. \endash  \plain \f1\super\lang1033\fs24 8\plain \f1\i\lang1033\fs24 Malachie episcopi\plain \f1\lang1033\fs24  (5.11.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2365, 2369. \endash  \plain \f1\super\lang1033\fs24 9\plain \f1\i\lang1033\fs24 Emundi episcopi et confessoris\plain \f1\lang1033\fs24  (16.11.) \endash  \plain \f1\super\lang1033\fs24 10\plain \f1\i\lang1033\fs24 Cecilie virginis\plain \f1\lang1033\fs24  (22.11.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2196, 2201, 2430, 2434. \endash  \plain \f1\super\lang1033\fs24 11\plain \f1\i\lang1033\fs24 Clementis pape et martiris\plain \f1\lang1033\fs24  (23.11.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2213, 2299. \endash  \plain \f1\super\lang1033\fs24 12\plain \f1\i\lang1033\fs24 Katherine virginis\plain \f1\lang1033\fs24  (25.11.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2226. \endash  \plain \f1\super\lang1033\fs24 13\plain \f1\i\lang1033\fs24 Eligii episcopi et confessoris\plain \f1\lang1033\fs24  (1.12.) \endash  \plain \f1\super\lang1033\fs24 14\plain \f1\i\lang1033\fs24 Nicolai episcopi\plain \f1\lang1033\fs24  (6.12.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2255. \endash  \plain \f1\super\lang1033\fs24 15\plain \f1\i\lang1033\fs24 Lucie virginis\plain \f1\lang1033\fs24  (13.12.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2259. \endash  \plain \f1\super\lang1033\fs24 16\plain \f1\i\lang1033\fs24 Thome apostoli\plain \f1\lang1033\fs24  (21.12.) \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2277}

