\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Cantica}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Im Kopfsteg: \plain \f1\i\lang1033\fs24 Cantica de dominica\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 1\plain \f1\i\lang1033\fs24 Domine, miserere nostri, te enim exspectauimus\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 13\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2503\plain \f1\lang1033\fs22 .\plain \f1\lang1033\fs24  \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\i\lang1033\fs24 Audite, qui longe estis\plain \f1\lang1033\fs22 .\plain \f1\scaps\lang1033\fs22  \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 13\plain \f1\lang1033\fs22 ;\plain \f1\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2504. \endash  (95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 3\plain \f1\i\lang1033\fs24 Miserere, domine, plebi tue\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 13\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2505. \endash  \plain \f1\i\lang1033\fs24 De pascha canticum\plain \f1\lang1033\fs24 . \plain \f1\super\lang1033\fs24 4\plain \f1\i\lang1033\fs24 Quis est iste, qui uenit de Edom\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 807\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2509. \endash  (96\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 5\plain \f1\i\lang1033\fs24 Venite et reuertamur ad dominum\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 807\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2510. \endash  \plain \f1\super\lang1033\fs24 6\plain \f1\i\lang1033\fs24 Exspecta me, dicit dominus\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 807\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2511. \endash  (96\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 7\plain \f1\i\lang1033\fs24 Uos sancti domini uocabimini\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2512. \endash  \plain \f1\super\lang1033\fs24 8\plain \f1\i\lang1033\fs24 Fulgebunt iusti, et tamquam scintille\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2071\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2513. \endash  \plain \f1\super\lang1033\fs24 9\plain \f1\i\lang1033\fs24 Reddet deus mercedem laborum\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2071\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2514. \endash  (97\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De vno martire\plain \f1\lang1033\fs24 . \plain \f1\super\lang1033\fs24 10\plain \f1\i\lang1033\fs24 Beatus uir, qui in sapiencia\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2096\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2515. \endash  \plain \f1\super\lang1033\fs24 11\plain \f1\i\lang1033\fs24 Benedictus uir, qui confidit in domino\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2096\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs22  Nr. 2516\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 12\plain \f1\i\lang1033\fs24 Beatus uir, qui inuentus est\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2096\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2517. \endash  \plain \f1\i\lang1033\fs24 De virginibus\plain \f1\lang1033\fs24 . \plain \f1\super\lang1033\fs24 13\plain \f1\i\lang1033\fs24 Audite me, diuini fructus\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2193\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2518. \endash  (97\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\super\lang1033\fs24 14\plain \f1\i\lang1033\fs24 Gaudens gaudebo in domino\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2193\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2519. \endash  \plain \f1\super\lang1033\fs24 15\plain \f1\i\lang1033\fs24 Non uocaberis ultra derelicta\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2193\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2520. \endash  (98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De sancta cruce\plain \f1\lang1033\fs24 . \plain \f1\super\lang1033\fs24 16\plain \f1\i\lang1033\fs24 Domine, audiui; Pro iniquitate; Egressus es in salutem\plain \f1\lang1033\fs24 . \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 1594\plain \f1\lang1033\fs22 ; \plain \f1\scaps\lang1033\fs24 Ma\plain \f1\scaps\lang1033\fs24 \u238 \'ee\plain \f1\scaps\lang1033\fs24 tre\plain \f1\lang1033\fs24  Nr. 2521-2523. \endash  \plain \f1\i\lang1033\fs24 Cantica de dedicacione\plain \f1\lang1033\fs24 . \plain \f1\super\lang1033\fs24 17\plain \f1\i\lang1033\fs24 Letatus sum. Nisi dominus. Lauda Ierusalem\plain \f1\lang1033\fs24 . Vgl. \plain \f1\scaps\lang1033\fs24 Waddell\plain \f1\lang1033\fs24  Nr. 2214.}

