\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -508\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Vetus testamentum cum prologis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit prologus sancti Jeronimi prespiteri de omnibus\plain \f1\lang1033\fs24 \u8249 \'8b (von Hand des Widmungseintrags erg\u228 \'e4nzt) \plain \f1\i\lang1033\fs24 Sacrarum Bibliarum libris\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Frater Ambrosius michi tua munuscula preferens}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 omnia qui se semper cogitat esse moriturum\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Stegm\plain \f1\scaps\lang1033\fs24 \u252 \'fc\plain \f1\scaps\lang1033\fs24 ller\plain \f1\lang1033\fs24 , RB 284\plain \f1\lang1033\fs24\cf1 ); drei Viertel von 1\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1  sowie 1\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1  unbeschrieben, mit Schreibervermerk: \plain \f1\i\lang1033\fs24\cf1 Hic non est defectum\plain \f1\lang1033\fs24\cf1 ; tats\u228 \'e4chlich besteht kein Textverlust. \endash  (3\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) RB 285, Gn;\plain \f1\lang1033\fs24  (23\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Ex; (40\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Lv; (52\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Nm; (72\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Dt; (90\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) RB 311, \plain \f1\lang1033\fs24\cf1 Ios, (104\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1  Z. 13-29) mit Zusatz: \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 et illo die accipientes Leuite archam testamenti domini\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 qui dominatus est illis decem annis et octo\plain \f1\lang1033\fs24\cf1 ; (104\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) Idc; (118\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) Rt; (120\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) \plain \f1\lang1033\fs24 RB 323,\plain \f1\lang1033\fs24\cf1  I Sm; (141\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) II Sm; (158\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) III Rg; (178\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) IV Rg; (196\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) \plain \f1\lang1033\fs24 RB 328,\plain \f1\lang1033\fs24\cf1  I Par; (212\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) II Par 1,1-16, \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sequitur prologus libri secundi paralipomenon, qui debet stare ante capitulum primum Confortatus est ergo etc., post hoc sequitur capitulum secundum huius libri\plain \f1\lang1033\fs24\cf1 \u8249 \'8b, \plain \f1\lang1033\fs24 RB 327, II Par 2,1-\plain \f1\lang1033\fs24\cf1 36,23; (233\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1  Z. 42-234\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) Oratio Manasse (\plain \f1\lang1033\fs24 RB 93,2). \endash  (234\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 )\plain \f1\lang1033\fs24\cf1  \plain \f1\lang1033\fs24 RB 330,\plain \f1\lang1033\fs24\cf1  I Esr; (240\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) II Esr; (249\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) IV Esr 1,1-2,48; (250\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) III Esr\plain \f1\lang1033\fs24 ; (260\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) IV Esr 3,1-16,78; (274\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) RB 332, Tb; (279\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) RB 335, Idt; (2