\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ewangelii nomen latine interpretatur bonum nunccium uel bona anuncciacio, et licet, cum bonum aliquod annuncciatur, semper dici possit ewangelium, proprie tamen hoc vocabulum obtinuit annuncciacio saluatoris \u8230 \'85}}\plain \f1\lang1033\fs24 ; (3\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Sequitur prologus. Matheus ex Iudea\plain \f1\lang1033\fs24  (Prologus monarchianus; vgl. \plain \f1\scaps\lang1033\fs24 Stegm\plain \f1\scaps\lang1033\fs24 \u252 \'fc\plain \f1\scaps\lang1033\fs24 ller\plain \f1\lang1033\fs24 , RB 590; \plain \f1\scaps\lang1033\fs24 Bruyne\plain \f1\lang1033\fs24 , Pr\u233 \'e9faces, S. 170f.). {\field{\*\fldinst HYPERLINK "hida://5650[1]/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Diuiditur secundum M[agistrum] Ni[colaum] de Lira in quattuor partes. In prima describitur ewangeliste status, in secunda scribendi modus ibi duorum in generacione \u8230 \'85}}\plain \f1\lang1033\fs24 ; (5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Mt 1: {\field{\*\fldinst HYPERLINK "hida://5650[2]/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Liber generacionis Ihesu Christi (Mt 1,1). Hoc ewangelium beati Mathei diuiditur in duas partes et primo ostendit Christum esse uerum hominem et uerum deum \u8230 \'85}}\plain \f1\lang1033\fs24 ; (12\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Mt 2; (19\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 3; (28\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Mt 4; (43\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 5; (92\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Mt 6; (128\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 7; (157\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 8; (166\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Mt 9; (178\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 10; (185\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Mt 11; (191\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 12. \endash  202\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -202\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer. \endash  (203\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Mt 13; (211\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 14; (215\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 15; (221\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Mt 16; (228\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 17; (233\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Mt 18; (248\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Mt 19; (256\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Mt 20; (264\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Mt 21; (272\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Mt 22; (281\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Mt 23; (291\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Mt 24; (302\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Mt 25; (315\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 26; (341\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 27; (356\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Mt 28, expl.: \u8230 \'85 \plain \f1\i\lang1033\fs24 quorum bonorum nos participes efficiat Ihesus Christus dominus noster, qui cum deo patre et spiritu sancto viuit et regnat vnus deus in secula benedictus. Amen. Deo gracias\plain \f1\lang1033\fs24 . \endash  Mit den bei \plain \f1\scaps\lang1033\fs24 Madre\plain \f1\lang1033\fs24 , S. 53f. aufgef\u252 \'fchrten Quaestionen: (34\plain \f1\super\lang1033\fs24 ra\plain \f1\lang