\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Laut {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kolophon}}\plain \f1\lang1033\fs20  auf 437\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  ist die Hs. 1452 geschrieben worden. Die verwendeten Papiersorten weisen in den s\u252 \'fcddeutschen (schw\u228 \'e4bischen) Raum. Das Nachlassinventar mit einer Liste der hinterlassenen B\u252 \'fccher des im Dezember 1452 verstorbenen Freisinger Bischofs {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johannes III. Gr\u252 \'fcnwalder}}\plain \f1\lang1033\fs20  nennt {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Item liber, qui sic incipit \u8218 \'82Divinum nobis per organum sapiencie\lquote }}\plain \f1\lang1033\fs20 ; demnach k\u246 \'f6nnte vorliegende Hs. aus Gr\u252 \'fcnwalders Besitz stammen (vgl. MBK 4,2 Nr. 80, S. 633 Z. 107f.). \endash  Mittelalterlicher {\field{\*\fldinst HYPERLINK "hida://5650[2]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Besitzvermerk}}\plain \f1\lang1033\fs20  auf I\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 : {\field{\*\fldinst HYPERLINK "hida://5650[2].5686/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Jste liber est sancte Marie et sancti Corbiniani martyris (darunter trotz Tilgung lesbar: confessoris) Frisingensis.}}}

