\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 2\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -118\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24    [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Antonius de Parma}}\plain \f1\lang1033\fs24 ]: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Postilla de tempore}}
\par \pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u220 \'dcber dem Text: \plain \f1\i\lang1033\fs24 Principium, finem, medium regat sancta Maria\plain \f1\lang1033\fs24  (Zeile dar\u252 \'fcber abgeschnitten). \u8250 \'9b\plain \f1\i\lang1033\fs24 Dominica prima in adventu domini\plain \f1\lang1033\fs24 \u8249 \'8b Text: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum appropinquasset \u8230 \'85 (Mt 21,1). Tempus quod hodie incipit et durat usque ad nativitatem domini}}\plain \f1\i\lang1033\fs24  vocatur ab ecclesia aduentus\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 est redempcio et redemptor vtriusque. Qui vivit et regnat cum deo patre in vnitate spiritus sancti deus per infinita secula. Amen etc. Explicit pustilla \plain \f1\lang1033\fs24 (!). (118\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  Explicit pustilla permensis \plain \f1\lang1033\fs24 (!).\plain \f1\i\lang1033\fs24  Dentur pro penna scriptori celica regna. {\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Finita et scripta est ista pustilla per dominum Erhardum Ottenhofer arcium liberalium baccalarium nec non rectorem parochialis ecclesie Sancti Martini in Neuching. Anno domini Mo CCCCo XXVIo in die sancti virgilii hora circa nona post meridiem etc.}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Sp\u228 \'e4ter hinzugesetzt:\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 compilato (?) de scriptura nova, antiquior autem scriptura scripta est per eundem Erhardum anno domini Mo CCCC XV \u8230 \'85 Finito libro laus domino Ihesu Christo}}\plain \f1\i\lang1033\fs24 . \plain \f1\lang1033\fs24 \endash  Nicht bei Schneyer verzeichnete Predigten: (36\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -37\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo de penitentia etc\plain \f1\lang1033\fs24 .\u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Penitenciam agite}}\plain \f1\lang1033\fs24\chcbpat17  \u8230 \'85 (Mt 3,2). {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ieremias propheta dicit: Anima que peccaverit ipsa morietur}}\plain \f1\lang1033\fs24  \u8230 \'85; (57\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -59\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequitur de eodem\plain \f1\lang1033\fs24  [feria 2\plain \f1\super\lang1033\fs24 a\plain \f1\lang1033\fs24  et communiter per ebdomadam]\u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sequitur quod facta cena et dominus illa nocte in Bethania quiescente}}\plain \f1\lang1033\fs24  \u8230 \'85; (59\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -61\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Audientes Pharisei \u8230 \'85 (Mt 22,34). Secundum hystoriam ecclesiasticam tres erant secte iudeorum}}\plain \f1\lang1033\fs24  \u8230 \'85 vgl. Uppsala, UB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 C 259}}\plain \f1\lang1033\fs24 , 94\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; (63\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -70\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Feria sexta in parasceue sermo\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Egressus Ihesus \u8230 \'85 (Io 18,1). Passio domini a 4or ewangelistis scripta est}}\plain \f1\lang1033\fs24   \u8230 \'85 vgl. u.a. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 14108}}\plain \f1\lang1033\fs24 , 186\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ; (72\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -73\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De beata virgine sermo\plain \f1\lang1033\fs24 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nolite me \u8230 \'85 (Rt 1,20). Dicta hystoria huius verbi potes incipere virginis amaritudines}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Zumkeller\plain \f1\scaps\lang1033\fs24 ,\plain \f1\lang1033\fs24  Manuskripte Nr. 432, dort Jacobus Parmensis zugewiesen; (73\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Maria Magdalena \u8230 \'85 (Mt 27,56). Hodie celebramus resurrectionem}}\plain \f1\lang1033\fs24  \u8230 \'85 GW 2248 Nr. 58. \endash  (14\plain \f1\super\lang1033\fs24 ra-vb\plain \f1\lang1033\fs24 ) Nachtrag von Schreiberhand: {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Stetit Iesus \u8230 \'85 (Lc 24,36). Dominus noster inter discipulos}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 3, S. 244 Nr. 291 (Jacobus de Voragine).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Die 63 Sermones stimmen nur teilweise mit der Editio princeps (GW 2248; BSB Ink A-643) \u252 \'fcberein, gr\u246 \'f6\u223 \'dfere N\u228 \'e4he besteht zur Druckfassung Paris 1515 (\plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium 1, S. 303-307 Nr. 184-228, die allerdings ohne die Sermones quadragesimales auskommt). Abfolge: \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium 1, S. 291-313 Nr. 184-187, 139f., 188-196, 233, 236, 245, 291, 259, 266, 272, 255, 294f., 300, 73, 315, 197-213, 110, 112, 216-228. \endash  \plain \f1\scaps\lang1033\fs20 Kaeppeli\plain \f1\lang1033\fs20 , Scriptores, Nr. 264. \endash  Gilles G. \plain \f1\scaps\lang1033\fs20 Meersseman\plain \f1\lang1033\fs20 , Le opere di fra Antonio Azaro Parmense O.P. nella biblioteca Nazionale di Monaco di Baviera, in: AFP 10 (1940), S. 20-47, Hs. verzeichnet S. 31.}

