\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 118\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -122\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones de dedicatione ecclesiae}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Sequitur sermo bonus de dedicacione ecclesie. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ecce tabernaculum \u8230 \'85 (Apc 21,3). Quia totum officium dedicationis}}\plain \f1\lang1033\fs24  \u8230 \'85 Fragment, Text bricht nach wenigen Zeilen ab \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (118\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Secuntur sermones de dedicacione ecclesie\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 etc. quorum primus est talis\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Si quis cognouerit plagam \u8230 \'85 (III Rg 8,38), Ecce tabernaculum \u8230 \'85 (Apc 21,3). Quoniam ad primum sciendum quod in domo scilicet celesti}}\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (119\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hodie in domo \u8230 \'85 (Lc 19,5). Verba ista moraliter}}\plain \f1\lang1033\fs24 \u8230 \'85; \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 (122\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In domo tua \u8230 \'85 (Lc 19,5). Si vis edificare}}\plain \f1\lang1033\fs24  \u8230 \'85; (122\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Schreibervermerk}}\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Scriptus velociter per Erhardum Ottenhoffer\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Sermones 1, 3, 4: \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium 3, S. 858f., Nr. 531, 522f. (Iordanus de Quedlinburgo). \endash  \plain \f1\scaps\lang1033\fs20 Zumkeller,\plain \f1\lang1033\fs20  Manuskripte Nr. 641.}

