\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo in dedicatione ecclesie\plain \f1\lang1033\fs24 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Et dixit \u8230 \'85 (Apc 21,5). Thronus, id est c[orpus?], quod nec lingwa exprimere potest}}\plain \f1\lang1033\fs24  \u8230 \'85, \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (160\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vidit Jacob \u8230 \'85 (Gen 28,12). Per istam scalam}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 9, S. 339 Nr. 187; \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (160\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnis qui petit \u8230 \'85 (Lc 11,10). Sollicite enim debemus competere dominum ut det nobis}}\plain \f1\i\lang1033\fs24  remissionem omnium peccatorum\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\super\lang1033\fs24 4\plain \f1\lang1033\fs24 (160\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Domus mea \u8230 \'85 (Mt 21,13). Hec verba dicit dominus in Mt et bene conveniunt huic festivitati}}\plain \f1\i\lang1033\fs24  quam hodie celebramus\plain \f1\lang1033\fs24  \u8230 \'85 vgl. Innsbruck, ULB {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. 764}}\plain \f1\lang1033\fs24 , 353\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ; \plain \f1\super\lang1033\fs24 5\plain \f1\lang1033\fs24 (161\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst