\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -186\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24     {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Jacobus de Voragine}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Legenda aurea}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit aliud pars nouum passionale\plain \f1\lang1033\fs24 \u8249 \'8b \endash  NC 85-89; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 80-84. \endash  (15\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Paulus ap. NC 90; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 85; endet S. 586\plain \f1\super\lang1033\fs24 186\plain \f1\lang1033\fs24 ; (20\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  Z. 9-21\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) mit Zusatz: \plain \f1\i\lang1033\fs24 Nero autem impunitus non extitit, sed pro hoc scelere et aliis que commisit manu propria se peremit\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ubi rana latitauerat lateranis, a latente rana nomen accipit\plain \f1\lang1033\fs24 . Parallel\u252 \'fcberlieferung: Berlin, SBB-PK, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ms. theol. lat. 4o 361}}\plain \f1\lang1033\fs24 , 91\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ; Hamburg, SUB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Theol. 1124}}\plain \f1\lang1033\fs24 , 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; Innsbruck, ULB, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. 267}}\plain \f1\lang1033\fs24 , 85\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 . \endash  (21\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) NC 91, 93; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 86, 89. \endash  (23\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Maria Magdalena. NC 96; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 92; mit Zusatz: (29\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -30\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Propter que omnia dicere de ipsa competit illud Apocalipsis xii\plain \f1\lang1033\fs24  (Apc 12,1-2): \plain \f1\i\lang1033\fs24 Mulier amicta sole, id est diuinitatis contemplacione \plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 quia eam in celo collocauit et sic patet totum\plain \f1\lang1033\fs24 . \endash  (30\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) NC 94-95, 98-100, 102-103, 105, 110-113; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 90-91, 94-96, 98-99, 101, 106-109. \endash  (53\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\lang1033\fs24\cf1 Afra v. et soc. m.: \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De sancta Affra uirgine et martyra\plain \f1\lang1033\fs24\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Tempore Dyocleciani Narcissus episcopus ad ciuitatem Augustam veniens}}\plain \f1\i\lang1033\fs24\cf1  casu \plain \f1\i\lang1033\fs24 ad mulierem nomine Affra\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 sicque eodem die quo sepulta est beata Afra passe sunt Hylaria, Digna, Eunomia et Eutropia cum palma martirii ad ipsam venientes\plain \f1\lang1033\fs24  \u8230 \'85 Amen. Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 14291}}\plain \f1\lang1033\fs24 , 232\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -233\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24\cf1 .\plain \f1\lang1033\fs24  \endash  (54\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) NC 114; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 110. \endash  (55\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -60\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Laurentius m. NC 117; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 113, endet S. 770\plain \f1\super\lang1033\fs24 259\plain \f1\lang1033\fs24 ; (60\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -61\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) exemplum 1: {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quidam sanctus abbas in magna veneracione habuit beatum Laurencium}}\plain \f1\i\lang1033\fs24 , qui cottidie rogauit eum ut reuelaret sibi meritum suum\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et hiis dictis angelus auxit predictum abbatem in locum suum\plain \f1\lang1033\fs24 . Parallel\u252 \'fcberlieferung: Uppsala, UB, {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 C 364}}\plain \f1\lang1033\fs24 , 187\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; (61\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) exemplum 2: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Parentes beati Laurencii diuites gentiles erant, quibus et multa plebs seruiebat}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et ibidem martyrium consummauit\plain \f1\lang1033\fs24 . Parallel\u252 \'fcberlieferung: Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. II. 1. 2o 222}}\plain \f1\lang1033\fs24 , 29\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 . \endash  (61\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) NC 118; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 114, endet S. 777\plain \f1\super\lang1033\fs24 62\plain \f1\lang1033\fs24 . \endash  (62\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Assumptio BMV. NC 119; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 115, S. 779\plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 -797\plain \f1\super\lang1033\fs24 315\plain \f1\lang1033\fs24  (mit Auslassungen); (67\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Jtem de assumpcione sancte Marie\plain \f1\lang1033\fs24 \u8249 \'8b M33 (\plain \f1\scaps\lang1033\fs24 Fleith\plain \f1\lang1033\fs24 , S. 337); \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 115, S. 797\plain \f1\super\lang1033\fs24 316\plain \f1\lang1033\fs24 -810\plain \f1\super\lang1033\fs24 528\plain \f1\lang1033\fs24 ; (71\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Einschub: \plain \f1\i\lang1033\fs24 Porro alia multa sunt ibi posita pocius ad simulacionem quam ad ueritatatem\plain \f1\lang1033\fs24  \u8230 \'85, enth\u228 \'e4lt u.a. (71\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 De reuelacione sancte Elysabeth\plain \f1\lang1033\fs24  [Schonaugiensis]: {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quadam uice cum in spiritu rapta fuisset, uidit in loco ualde remoto quoddam sepulchrum}}\plain \f1\i\lang1033\fs24  multo lumine circumfulsum\plain \f1\lang1033\fs24  \u8230 \'85, (71\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod beata Maria sit corpore assumpta et anima racio quadruplex est}}\plain \f1\lang1033\fs24  \u8230 \'85, (71\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -72\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Notandum est ergo, quod gloriosa uirgo Maria assumpta et exaltata est integraliter}}\plain \f1\i\lang1033\fs24 , honorabiliter, letanter et excellenter\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 celestem quoque miliciam tunc ineffabili leticia exultasse\plain \f1\lang1033\fs24 . Parallel\u252 \'fcberlieferung: Berlin, SBB-PK, {\field{\*\fldinst HYPERLINK "hida://5007[6].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ms. theol. lat. 4o 361}}\plain \f1\lang1033\fs24 , 111\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ; (73\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -74\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) mit Zusatz: \plain \f1\i\lang1033\fs24 Quidam miles cum ad bellum per quandam uillam transitum faceret, uidit unam pulcherrimam uirginem\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et sicut in cimiterium sepultus est\plain \f1\lang1033\fs24 . Parallel\u252 \'fcberlieferung: Korneuburg, StadtA, {\field{\*\fldinst HYPERLINK "hida://5007[7].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. 1751}}\plain \f1\lang1033\fs24 , 50\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 . \endash  (74\plain \f1\super\lang1033\fs24 rab\plain \f1\lang1033\fs24 ) NC 121, 120, 123-125, 130-131, 137, 140-141, 145-146, 149, 156, 158-159, 162-163, 161, 155, 166-167; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 117, 116, 119-121, 123, 127, 131, 136-137, 141-142, 145, 152, 154-155, 158-159, 157, 151, 162-163\plain \f1\lang1033\fs24\cf1 . \endash  (155\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 ) Elisabeth vid. lantgravia Thuringiae\plain \f1\lang1033\fs24 :\plain \f1\lang1033\fs24\cf1  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Gerdrudis (vielm. Isentrudis) uidua religiosa de Hyrsaugia, que fuit in familia Elyzabet circiter annos quinque}}\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 quia simul tunc fuerunt in familia Elizabeth\plain \f1\lang1033\fs24\cf1 . BHL 2493f. \plain \f1\lang1033\fs24 Libellus de dictis quattuor ancillarum.\plain \f1\lang1033\fs24\cf1  Druck:\plain \f1\lang1033\fs24  Albert \plain \f1\scaps\lang1033\fs24 Huyskens\plain \f1\lang1033\fs24 , Der sog. Libellus de dictis quatuor ancillarum s. Elisabeth confectus, hrsg. und erl. von Albert \plain \f1\scaps\lang1033\fs24 Huyskens\plain \f1\lang1033\fs24 . Kempten/M\u252 \'fcnchen 1911, S. 16-33. \endash  (158\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24\cf1 ) Conclusio vitae beatae Elisabeth: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Licet autem veridica tam testium iuratorum}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 in quem firmiter credidit Jhesus Christus dominus noster, cui est\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 . BHL 2493g. Druck: \plain \f1\scaps\lang1033\fs24 Huyskens\plain \f1\lang1033\fs24 , S. 80-86. \endash  (160\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) NC 169-170, 172, 180, 182; \plain \f1\scaps\lang1033\fs24 Maggioni\plain \f1\lang1033\fs24  Nr. 165-166, 168, 176, 178. \endash  (186\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[8]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Schreibervermerk}}\plain \f1\lang1033\fs24 : \u8250 \'9b\plain \f1\i\lang1033\fs24 Item notandum quod iste liber scilicet aliud pars nouum passionale scriptus est a domino Hainrico conanico\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 in Pa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wrberck\plain \f1\lang1033\fs24  (Ortsangabe radiert) \plain \f1\i\lang1033\fs24 monasterii sanctorum Petri et Pauli apostolorum in Pa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wrberck sub anno domini M\plain \f1\i\super\lang1033\fs24 o \plain \f1\i\lang1033\fs24 CCCC\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  Anno v\plain \f1\i\super\lang1033\fs24 to\plain \f1\i\lang1033\fs24  proxima die sabbati ante dominicam, qua canitur officium Cantate domino canticum nouum et cetera\plain \f1\lang1033\fs24  (Cantus 001762) \plain \f1\i\lang1033\fs24 infra pasche et pentecosten et cetera\plain \f1\lang1033\fs24 \u8249 \'8b. Darunter von j\u252 \'fcngerer Hand: \plain \f1\i\lang1033\fs24 Nota quod ego Mathias Ekkl\plain \f1\lang1033\fs24 . \endash  (186\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -187\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Nach Fleith, S. 175f. (diese Hs. mit Sigle \plain \f1\i\lang1033\fs20 LA\plain \f1\lang1033\fs20  462) fehlen folgende Legenden: NC 92, 97, 101, 104, 106-109, 115-116, 122, 126-129, 132-136, 138-139, 142-144, 147-148, 150-154, 157, 160, 164-165, 168, 171, 173-179, 181 (\u252 \'fcberliefert in {\field{\*\fldinst HYPERLINK "hida://5007[8].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 6509}}\plain \f1\lang1033\fs20 ). \endash  Als Sondergut werden die Legende der hl. Afra (A22) sowie der \plain \f1\i\lang1033\fs20 Modus Mariae assumptionis\plain \f1\lang1033\fs20  (M33) \u252 \'fcberliefert. Die von Fleith aufgrund des Textinitiums der hl. Gertrudis zugeordnete Legende auf \plain \f1\lang1033\fs20\cf1 155\plain \f1\super\lang1033\fs20\cf1 rb\plain \f1\lang1033\fs20\cf1 -158\plain \f1\super\lang1033\fs20\cf1 va\plain \f1\lang1033\fs20\cf1  \plain \f1\lang1033\fs20 (Sigle G28) ist ein Auszug aus dem sog. \plain \f1\i\lang1033\fs20 Libellus\plain \f1\lang1033\fs20 , in dem der Kanonisationsprozess der hl. \plain \f1\lang1033\fs20\cf1 Elisabeth von Th\u252 \'fcringen von 1232 bis 1235 protokolliert wurde. Er \u252 \'fcberliefert \plain \f1\lang1033\fs20 die \plain \f1\lang1033\fs20\cf1 Zeugenaussagen von Elisabeths Hofdamen \plain \f1\lang1033\fs20 Guda und Isentrud von H\u246 \'f6rselgau sowie der beiden Marburger Spitalschwestern Irmgard und Elisabeth. Vorliegende Hs. enth\u228 \'e4lt lediglich die Aussage der Isentrudis sowie die Conclusio.}

