\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 1\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -179\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Marcus Tullius Cicero}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Epistolae ad familiares. Libri I-XVI}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lib 1: \u8250 \'9b\plain \f1\i\lang1033\fs24 M. T. CICERONIS AD PVBLIVM LENTVLVUM ET AD ALIOS EPISTVLARVM LIBER PRIMVS INCIPIT\plain \f1\lang1033\fs24 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ego omni officio ac potius pietate erga te ceteris satisfatio omnibus}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 tamquam Vlixes cognosces tuorum neminem. Vale\plain \f1\lang1033\fs24 . \endash  (11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Lib. 2; (19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) lib. 3; (28\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) lib. 4; (38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) lib. 5; (52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) lib. 6; (63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) lib. 7; (75\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) lib. 8; (84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) lib. 9; (96\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) lib. 10; (113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) lib. 11; (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) lib. 12; (135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) lib. 13; (156\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) lib. 14; (161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) lib. 15; (172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) lib. 16: [V]\plain \f1\i\lang1033\fs24 Ide, quanta sit in te suauitas: duas horas Thyrei fuimus\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 etiamsi te ueniens in medio foro uidero, dissuauiabo. Me ama. Vale\plain \f1\lang1033\fs24 . Reihenfolge der Briefe vertauscht: Nr. 5, 7, 1-4, 6, 8-9, 11-12, 10, 15, 14, 13, 16-27. \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kolophon}}\plain \f1\lang1033\fs24 : \u8250 \'9b\plain \f1\i\lang1033\fs24 M. T. Ciceronis epistularum liber sextus decimus ad Tironem felicissime explicit, quare gratias immensas Christo referrimus. Significacio litterarum antiquarum et breuiature antique subsequitur\plain \f1\lang1033\fs24 \u8249 \'8b \endash  (178\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -179\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Abk\u252 \'fcrzungsverzeichnis. \endash  (179\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -184\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) leer (Raum f\u252 \'fcr ein Stellenverzeichnis der in den Kommentarspalten notierten Stich- und Schlagworte?).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Griechische Zitate wurden nicht ausgef\u252 \'fchrt (Textl\u252 \'fccken u.a. auf 22\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Z. 31, 86\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Z. 1-2, 87\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Z. 15f. 20, 88\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Z. 29-30, 95\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Z. 17, 141\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Z. 26. 30-33, 151\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Z. 6, 153\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Z. 18, 169\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Z. 14f. 18. 24. 32, 170\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Z. 13-18. 29, 173\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Z 4f. 12). \endash  Druck (in Auswahl): M. Tulli Ciceronis Epistulae ad familiares libri I-XVI, ed. David R. \plain \f1\scaps\lang1033\fs20 Shackleton Bailey\plain \f1\lang1033\fs20 . Stuttgart 1988 (Bibliotheca scriptorum Graecorum et Romanorum Teubneriana). \endash  Marcus Tullius Cicero. Epistolae ad familiares. An seine Freunde. Lateinisch und deutsch, hrsg. und \u252 \'fcbers. von Helmut \plain \f1\scaps\lang1033\fs20 Kasten\plain \f1\lang1033\fs20 . M\u252 \'fcnchen u.a. 1989 (Sammlung Tusculum).}

