\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Vorsatzbl. aus Pergament. Moderne Bleistiftfoliierung. Wasserzeichen: \plain \f1\super\lang1033\fs20 1\plain \f1\lang1033\fs20 Hand mit Mond, Abb. s. WZIS DE5580-Clm27031_68/69; \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 Beere, Abb. s. WZIS DE5580-Clm27031_107; \plain \f1\super\lang1033\fs20 3\plain \f1\lang1033\fs20 Hand mit Stern, Abb. s. WZIS DE5580-Clm27031_176/178; \plain \f1\super\lang1033\fs20 4\plain \f1\lang1033\fs20 Ochse, Abb. s WZIS DE5580-Clm27031_179/183; \plain \f1\super\lang1033\fs20 5\plain \f1\lang1033\fs20 Schl\u252 \'fcssel, Abb. s. WZIS DE5580-Clm27031_194; \plain \f1\super\lang1033\fs20 6\plain \f1\lang1033\fs20 S\u228 \'e4ule mit Krone, Abb. s. WZIS DE5580-Clm27031_202/239; \plain \f1\super\lang1033\fs20 7\plain \f1\lang1033\fs20 Blume, Abb. s. WZIS DE5580-Clm27031_242/251; \plain \f1\super\lang1033\fs20 8\plain \f1\lang1033\fs20 Ochsenkopf, Abb. s. WZIS DE5580-Clm27031_312; \plain \f1\super\lang1033\fs20 9\plain \f1\lang1033\fs20 Mond, Abb. s. WZIS DE5580-Clm27031_314/316. \endash  Lagen: 1\plain \f1\super\lang1033\fs20 I\plain \f1\lang1033\fs20  + VIII\plain \f1\super\lang1033\fs20 16\plain \f1\lang1033\fs20  + 13 VI\plain \f1\super\lang1033\fs20 172\plain \f1\lang1033\fs20  + III\plain \f1\super\lang1033\fs20 178\plain \f1\lang1033\fs20  + 11 VI\plain \f1\super\lang1033\fs20 310\plain \f1\lang1033\fs20  + V\plain \f1\super\lang1033\fs20 320\plain \f1\lang1033\fs20 . Teilweise Reklamanten am Lagenende. Schriftraum: 19-22 \u215 \'d7 11,5-13; 29-37 Zeilen. (1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -175\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cursiva Libraria}}\plain \f1\lang1033\fs20  von Hand 1, gelegentliche Randvermerke wohl ebenfalls von dieser Hand; (179\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -320\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hybrida Libraria}}\plain \f1\lang1033\fs20  von Hand 2. Teilweise rubriziert. 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  rot-blau gespaltene Initialen \u252 \'fcber 4 bzw. 10 Zeilen; an den Psalmenanf\u228 \'e4ngen rote Lombarden, vereinzelt mit Fleuronn\u233 \'e9e.}

