\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Versus de libris sententiarum cum commentario}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnis doctrina uel rerum est uel signorum. Res vero alie sunt quibus fruendum est}}\plain \f1\i\lang1033\fs24 , alie quibus utendum est\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 id quo fruendum est\plain \f1\lang1033\fs24 . Vers: \plain \f1\i\lang1033\fs24 Res docet utendas instinccio \plain \f1\lang1033\fs24 (!)\plain \f1\i\lang1033\fs24  prima fruendas\plain \f1\lang1033\fs24  \u8230 \'85, Kommentar: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hoc verba et pia fide tenendum est, quod trinitas sit vnus solus et verus deus}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 Et sic est finis illorum versuum super quatuor libros sentenciarum\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Stegm\plain \f1\scaps\lang1033\fs20 \u252 \'fc\plain \f1\scaps\lang1033\fs20 ller\plain \f1\lang1033\fs20 , RC 17 (Hs. genannnt). \endash  \plain \f1\scaps\lang1033\fs20 Walther\plain \f1\lang1033\fs20 , Initia Nr. 16609 (Hs. genannt). \endash  Parallel\u252 \'fcberlieferung aus Ebersberg: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Clm 5856}}\plain \f1\lang1033\fs20 ,241.}

