\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Sammlung mit 92 Homilien f\u252 \'fcr den Jahreskreis, einsetzend mit dem Samstag vor Ostern; Abfolge (Nr.-Angabe nach PL 95): Nr. 122, 123, 125, 127, 129, 131-133, 135, 157, 141, 137-140, 143, 145-147; (40\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Hrabanus Maurus, Homiliae in Evangelia 62, PL 110, 263D-266C; (43\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Nr. 153f.; (44\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Ambrosius, Expositio in Evangelium secundum Lucam 4,57-67, PL 15, 1629C-1633A; (47\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Nr. 159-162; (59\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Gr\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 goire\plain \f1\lang1033\fs24  II,57; (60\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Barr\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\lang1033\fs24 , B II 25; (61\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Barr\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\lang1033\fs24 , B II 27; (62\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Gr\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 goire\plain \f1\lang1033\fs24  II,61; (64\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Gr\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 goire\plain \f1\lang1033\fs24  II,62; (65\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Nr. 169; (68\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Beda, Homiliae III,10, PL 94, 289C-290C; (68\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Nr. 174, 175, 182, 154, 184; (75\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Gr\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 goire\plain \f1\lang1033\fs24  II,75 und 76; (76\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Nr. 180, 186; (77\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Audientes Pharisaei \u8230 \'85 (Mt 22,34-36). Conuenerunt ut multitudine vincerent}}\plain \f1\lang1033\fs24  \u8230 \'85 nur der Anfang wie Rabanus Maurus, Commentum in Mt, lib. 6 c. 22,6, PL 107, 1061C; (79\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Nr. 188, 189, (85\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Gr\plain \f1\scaps\lang1033\fs24 \u233 \'e9\plain \f1\scaps\lang1033\fs24 goire\plain \f1\lang1033\fs24  II,94 und 95; (86\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Nr. 196, 197; 7, 2, 11, 17, 18, 20, 21, 29, 36, 37, 45, 42, 48, 50-55; (133\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Beda, Homiliae I,15, PL 94,79B-83B; (134\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) 59, 61, 64, 72, 75, 77, 78, 80, 89, 97, 105, 113, 24, 118, 58.
