\pard\keep\keepn\fi-870\li870\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 325\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -362\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Henricus de Frimaria}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tractatus decem preceptorum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipit tractatus decem preceptorum editus a magistro Heinrico de Brunaria\plain \f1\lang1033\fs24\cf1  (!) \plain \f1\i\lang1033\fs24\cf1 ordinis fratrum heremitarum sancti Augustini\plain \f1\lang1033\fs24\cf1 \u8249 \'8b (325\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 ) Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Audi Israhel precepta domini (Cantus 006143). In verbis propositis spiritus sanctus circa diuina precepta tria tangit}}\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  (328\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) Text: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Primum preceptum appropriate respicit personam patris}}\plain \f1\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 quod uinum nobis inditum gloriose virginis prestare dignetur cuius filius benedictus qui cum patre\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 Amen\plain \f1\lang1033\fs24\cf1 . \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Explicit decalogus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20\cf1 Druck: Henricus de Frimaria, De decem preceptis, ed. Bertrand-G. \plain \f1\scaps\lang1033\fs20\cf1 Guyot\plain \f1\lang1033\fs20\cf1 . Pisa 2005 (Centro di Cultura Medievale 14), S. 3-183, XXXII (Hs. genannt). \endash  \plain \f1\scaps\lang1033\fs20\cf1 Madre\plain \f1\lang1033\fs20\cf1 , Nikolaus von Dinkelsb\u252 \'fchl, S. 330f. Nr. 11. \endash  \plain \f1\scaps\lang1033\fs20\cf1 Zumkeller\plain \f2\lang1033\fs20\cf1 , \plain \f1\lang1033\fs20\cf1 Manuskripte Nr. 325 (Hs. genannt). \endash  \plain \f1\scaps\lang1033\fs20\cf1 Bloomfield\plain \f2\lang1033\fs20\cf1 , \plain \f1\lang1033\fs20\cf1 Incipits Nr.\plain \f2\lang1033\fs20\cf1  \plain \f1\lang1033\fs20\cf1 526. \endash  Robert G. \plain \f1\scaps\lang1033\fs20\cf1 Warnock\plain \f1\lang1033\fs20\cf1 , in: \u178 \'b2VL 3 (1981), Sp. 730-737. \endash  \plain \f1\scaps\lang1033\fs20\cf1 Bloomfield\plain \f1\lang1033\fs20\cf1 , Suppl. Nr.\plain \f2\lang1033\fs20\cf1  \plain \f1\lang1033\fs20\cf1 526.}

