\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Incipit Epistola sancti Cirilli Jerosolimitani episcopi ad beatum Augustinum doctorem eximium de miraculis beati Jeronimi doctoris magnifici\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Venerabili viro episcoporum eximio Augustino ypponensi}}\plain \f1\i\lang1033\fs24  presuli Cirillus Hierosolimitanus pontifex\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 mei, Augustine karissime, in tuis orationibus memor esto. Deo gratias\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kolophon}}\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Explicit epistola\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 anno lxx omnium sanctorum\plain \f1\lang1033\fs24 .
