\pard\keep\keepn\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Conradus de Ebraco O. Cist.}}\plain \f1\b\lang1033\fs24  et {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes de Braculis OESA}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Quaestio de cognitione animae Christi}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Determinatio Conradi: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Utrum beata Christi anima in eterna sapientia cognoscat omnia cognoscibilia}}\plain \f1\i\lang1033\fs24 . Et arguitur quod non\plain \f1\lang1033\fs24  \u8230 \'85, (8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Resumptio Johannis: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In determinacione huius questionis, utrum beata Christi anima in eterna dei sapiencia}}\plain \f1\i\lang1033\fs24  cognoscat omnia cognoscibilia, posui aliquas conclusiones\plain \f1\lang1033\fs24  \u8230 \'85, (49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Replicatio Conradi: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Contra dicta resumpte mee de noticia anime Christi replicat magister reverendus}}\plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 Et hec cum omni reverencia sint responsa ad replicata sepedicti magistri mei reverendi, cui mea scripta et me humiliter recommendo\plain \f1\lang1033\fs24 . (80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Rotulus de quo fit mencio in premissis. Infrascripta puncta visa sunt michi suspecta \plain \f1\lang1033\fs24 \u8230 \'85\endash \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Explicit determinatio questionis de cognitione anime Christi reverendi magistri Conradi}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  [de Ebrach] s}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 acre theologie doctoris, unacum resumpta eiusdem necnon solucionibus racionum replicatarum contra eundem per reverendum magistrum}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Johannem] }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 de Braculis sacre eiusdem theologie professoris finita anno domini 1391\u176 \'b0 proxima feria quinta ante Georii }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [19}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 . }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Apr}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 il}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  1391] }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 in principio hore 13}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs24\chcbpat17 me}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  per Bertholdum}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Puchhauser] }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 de Ratispona}}\plain \f1\lang1033\fs24 . \endash  81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -81a\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
